from typing import List

class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        def is_closely_greater(w: str, z: str) -> bool:
            if w <= z:
                return False
            z1 = z[0]
            w1 = w[0]
            return w1 == chr(ord(z1) + 1) or w1 == z1

        a_ptr = 0
        b_ptr = 0
        turn = True  # True for Alice's turn, False for Bob's

        # Alice plays first with her smallest word
        current_word = a[a_ptr]
        a_ptr += 1

        while True:
            if turn:
                # Alice's turn
                found = False
                while b_ptr < len(b):
                    if is_closely_greater(b[b_ptr], current_word):
                        current_word = b[b_ptr]
                        b_ptr += 1
                        found = True
                        break
                    b_ptr += 1
                if not found:
                    return True  # Bob cannot play, Alice wins
            else:
                # Bob's turn
                found = False
                while a_ptr < len(a):
                    if is_closely_greater(a[a_ptr], current_word):
                        current_word = a[a_ptr]
                        a_ptr += 1
                        found = True
                        break
                    a_ptr += 1
                if not found:
                    return False  # Alice cannot play, Bob wins

            turn = not turn

