from typing import List

class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        def get_smallest_valid(last_char: str, words: List[str]) -> str:
            target = chr(ord(last_char) + 1)
            i = 0
            while i < len(words):
                if words[i][0] == last_char:
                    i += 1
                elif words[i][0] == target:
                    return words[i]
                else:
                    break
            return None

        # Extract helper to avoid code duplication
        def process_turn(player_list: List[str], player_ptr: int, last_char: str, is_alice: bool) -> tuple:
            valid_word = get_smallest_valid(last_char, player_list[player_ptr:])
            if valid_word is None:
                return None, player_ptr, is_alice

            new_ptr = player_ptr + (player_list[player_ptr:].index(valid_word) + 1)
            return valid_word, new_ptr, not is_alice

        alice_turn = True
        a_idx = 0
        b_idx = 0

        # Alice plays her first word
        current_word = a[a_idx]
        a_idx += 1

        while True:
            if alice_turn:
                next_w, a_idx, alice_turn = process_turn(a, a_idx, current_word[0], alice_turn)
                if next_w is None:
                    return False
                current_word = next_w
            else:
                next_w, b_idx, alice_turn = process_turn(b, b_idx, current_word[0], alice_turn)
                if next_w is None:
                    return True
                current_word = next_w

