from typing import List

class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        # Algorithm/Data-Structure Variant: Use recursion instead of iteration
        def solve(last_char: str, a_idx: int, b_idx: int, is_alice: bool) -> bool:
            # Helper to find next word
            target = chr(ord(last_char) + 1)

            # Find next valid word in current list
            words = a if is_alice else b
            ptr = a_idx if is_alice else b_idx

            found = None
            for i in range(ptr, len(words)):
                if words[i][0] == last_char:
                    continue
                elif words[i][0] == target:
                    found = words[i]
                    next_ptr = i + 1
                    break
                else:
                    break

            if found is None:
                return not is_alice # Current player loses, so other wins

            if is_alice:
                return solve(found[0], next_ptr, b_idx, False)
            else:
                return solve(found[0], a_idx, next_ptr, True)

        # Alice starts with her smallest word
        if not a:
            return False

        start_word = a[0]
        return solve(start_word[0], 1, 0, False)

