class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        # Meaning-Preserving Rewrite: Rename variables and convert list slicing to index tracking
        def locate_best(last_char: str, candidates: List[str], start_idx: int) -> tuple:
            target_char = chr(ord(last_char) + 1)
            idx = start_idx
            while idx < len(candidates):
                char_at_start = candidates[idx][0]
                if char_at_start == last_char:
                    idx += 1
                elif char_at_start == target_char:
                    return candidates[idx], idx + 1
                else:
                    break
            return None, -1

        # State variables
        player_is_alice = True
        a_pos = 0
        b_pos = 0

        # Initial move by Alice
        if not a:
            return False

        current_played = a[a_pos]
        a_pos += 1

        # Game loop using while condition on player state
        while True:
            if player_is_alice:
                # Alice tries to play
                best_word, new_a_pos = locate_best(current_played[0], a, a_pos)
                if best_word is None:
                    return False
                current_played = best_word
                a_pos = new_a_pos
            else:
                # Bob tries to play
                best_word, new_b_pos = locate_best(current_played[0], b, b_pos)
                if best_word is None:
                    return True
                current_played = best_word
                b_pos = new_b_pos

            player_is_alice = not player_is_alice

