class Solution:
    def search(self, nums: List[int], target: int) -> int:
        n = len(nums)

        def find_rotation_point(arr):
            low, high = 0, len(arr) - 1
            while low < high:
                mid = (low + high) // 2
                if arr[mid] > arr[high]:
                    low = mid + 1
                else:
                    high = mid
            return low

        pivot = find_rotation_point(nums)
        start, end = 0, n - 1

        if target >= nums[pivot] and target <= nums[end]:
            start, end = pivot, end
        else:
            start, end = 0, pivot - 1

        while start <= end:
            mid = (start + end) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                start = mid + 1
            else:
                end = mid - 1

        return -1

