from typing import List

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        def binary_search(left_idx, right_idx):
            if left_idx > right_idx:
                return -1

            mid_idx = (left_idx + right_idx) // 2

            if nums[mid_idx] == target:
                return mid_idx

            # Determine which side is sorted
            if nums[left_idx] <= nums[mid_idx]:
                # Left side is sorted
                if nums[left_idx] <= target < nums[mid_idx]:
                    return binary_search(left_idx, mid_idx - 1)
                else:
                    return binary_search(mid_idx + 1, right_idx)
            else:
                # Right side is sorted
                if nums[mid_idx] < target <= nums[right_idx]:
                    return binary_search(mid_idx + 1, right_idx)
                else:
                    return binary_search(left_idx, mid_idx - 1)

        return binary_search(0, len(nums) - 1)

