class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        def can_extend(current_max: int, next_coin: int) -> bool:
            return next_coin <= current_max + 1

        coins.sort()
        limit = 0
        for coin in coins:
            if not can_extend(limit, coin):
                break
            limit += coin
        return limit + 1

