class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        # Algorithm variant: Use a set to track reachable sums (less efficient but valid alternative structure)
        # Note: This is a structural/algorithmic mutation that changes the approach entirely 
        # to demonstrate diversity, though less optimal than the greedy sort method.
        # However, per instructions, we must preserve the class signature and be runnable.
        # We will implement a DP-like set expansion which is a different algorithm.

        reachable = {0}
        coins.sort()
        for coin in coins:
            new_reachable = set()
            for r in reachable:
                if r + coin > sum(reachable) + coin + 1: 
                    # Heuristic boundary check to mimic the greedy property in this context
                    pass 
                else:
                    new_reachable.add(r + coin)
            reachable.update(new_reachable)

        # Count consecutive from 0
        count = 0
        while count in reachable:
            count += 1
        return count

