class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        MOD = 10**9 + 7

        # dp[i][j] represents the number of paths to move out of the boundary 
        # starting from cell (i, j) with exactly 'moves' steps allowed.
        # We iterate from 1 to maxMove moves.

        # Base case: 0 moves -> 0 paths for any cell inside.
        dp = [[0] * n for _ in range(m)]

        for k in range(1, maxMove + 1):
            new_dp = [[0] * n for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    count = 0
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = i + di, j + dj
                        if not (0 <= ni < m and 0 <= nj < n):
                            count += 1
                        else:
                            count = (count + dp[ni][nj]) % MOD
                    new_dp[i][j] = count
            dp = new_dp

        return dp[startRow][startColumn]

