                    ops_count += 1
                temp_n //= 2
                current_bit_len += 1
            if current_bit_len > highest_bit_length:
                highest_bit_length = current_bit_len

        if highest_bit_length > 0:
            ops_count += (highest_bit_length - 1)

        return ops_count

