class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        pairs_map = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}
        keys = ['0', '1', '6', '8', '9']

        def get_strobogrammatic(n):
            if n == 0:
                return [""]
            if n == 1:
                return ["0", "1", "8"]

            inner_list = get_strobogrammatic(n - 2)
            result_list = []

            for mid in inner_list:
                for k in keys:
                    v = pairs_map[k]
                    # Skip leading zero unless the number is just "0" (handled by n=1 case above)
                    if n != 1 and k == '0':
                        continue

                    result_list.append(k + mid + v)
            return result_list

        def is_valid(s, l_bound, h_bound):
            len_s = len(s)
            len_l = len(l_bound)
            len_h = len(h_bound)

            if len_s < len_l or len_s > len_h:
                return False

            if len_s == len_l and s < l_bound:
                return False

            if len_s == len_h and s > h_bound:
                return False

            return True

        total_count = 0
        len_low = len(low)
        len_high = len(high)

        for length in range(len_low, len_high + 1):
            candidates = get_strobogrammatic(length)
            for cand in candidates:
                if is_valid(cand, low, high):
                    total_count += 1

        return total_count

