class Solution:
    def longestIdealString(self, s: str, k: int) -> int:
        # dp[i] will store the length of the longest ideal subsequence ending with character chr(i)
        dp = [0] * 26  # for each lowercase letter a-z

        for ch in s:
            idx = ord(ch) - ord('a')
            # Check all characters within k distance from current character
            max_len = 0
            for i in range(max(0, idx - k), min(25, idx + k) + 1):
                max_len = max(max_len, dp[i])
            dp[idx] = max(dp[idx], max_len + 1)

        return max(dp)
