class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Not enough cables to connect all computers (at least n - 1 edges needed)
        if len(connections) < n - 1:
            return -1

        adj = [[] for _ in range(n)]
        for u, v in connections:
            adj[u].append(v)
            adj[v].append(u)

