        components = 0

        def dfs(node):
            stack = [node]
            while stack:
                curr = stack.pop()
                if not visited[curr]:
                    visited[curr] = True
                    for neighbor in adj[curr]:
                        if not visited[neighbor]:
                            stack.append(neighbor)

        for i in range(n):
