class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n == m:
            return 1
        if n == 0 or m == 0:
            return 0

        # Memoization cache
        from functools import lru_cache

        @lru_cache(None)
        def dp(heights):
            if all(h == n for h in heights):
                return 0

            min_squares = float('inf')
            leftmost = min(range(m), key=lambda i: heights[i])
            h = heights[leftmost]

            max_square_size = min(m, n - h)

            # Try placing square of size s at leftmost position
            for s in range(1, max_square_size + 1):
                new_heights = list(heights)
                for i in range(leftmost, leftmost + s):
                    new_heights[i] += s
                min_squares = min(min_squares, 1 + dp(tuple(new_heights)))

            return min_squares

        return dp(tuple([0] * m))
