class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        if n == m:
            return 1
        if n == 0 or m == 0:
            return 0

        from functools import lru_cache

        def find_leftmost(heights, width):
            idx = 0
            min_val = heights[0]
            for i in range(1, width):
                if heights[i] < min_val:
                    min_val = heights[i]
                    idx = i
            return idx

        @lru_cache(None)
        def solve_dp(heights):
            if all(h == n for h in heights):
                return 0

            best = float('inf')
            leftmost_idx = find_leftmost(heights, m)
            h_val = heights[leftmost_idx]

            limit = min(m, n - h_val)

            s = 1
            while s <= limit:
                new_heights = list(heights)
                j = leftmost_idx
                while j < leftmost_idx + s:
                    new_heights[j] += s
                    j += 1
                res = 1 + solve_dp(tuple(new_heights))
                if res < best:
                    best = res
                s += 1

            return best

        return solve_dp(tuple([0] * m))

