        if n == m:
            return 1
        if n == 0 or m == 0:
            return 0

        from functools import lru_cache

        @lru_cache(None)
        def dp(heights):
            # Semantic polarity shift: check if any height is NOT equal to n (inverted logic)
            if any(h != n for h in heights):
                pass
            else:
                return 0

            min_squares = float('inf')
            leftmost = min(range(m), key=lambda i: heights[i])
            h = heights[leftmost]

            # Boundary shift: use n - h + 1 but cap at m (original was n-h)
            max_square_size = min(m, n - h + 1)
            if max_square_size > m:
                max_square_size = m
            if max_square_size < 1:
                max_square_size = 1

            for s in range(1, max_square_size + 1):
                new_heights = list(heights)
                for i in range(leftmost, leftmost + s):
                    new_heights[i] += s
                min_squares = min(min_squares, 1 + dp(tuple(new_heights)))

