from typing import List
import heapq

class Solution:
    def timeTaken(self, arrival: List[int], state: List[int]) -> List[int]:
        n = len(arrival)
        result = [0] * n
        time = 0
        i = 0  # Pointer to the next person to consider

        # Priority queues for people waiting to enter or exit
        enter_queue = []  # (index, arrival_time)
        exit_queue = []   # (index, arrival_time)

        last_used_state = -1  # -1 means door was not used in previous second

        while i < n or enter_queue or exit_queue:
            # Add all people who arrive at current time to appropriate queue
            while i < n and arrival[i] <= time:
                if state[i] == 0:
                    heapq.heappush(enter_queue, (i, arrival[i]))
                else:
                    heapq.heappush(exit_queue, (i, arrival[i]))
                i += 1

            # Determine which group gets to go next based on rules
            next_dir = -1
            if not enter_queue and not exit_queue:
                # No one is waiting, move time forward to next arrival
                if i < n:
                    time = arrival[i]
                continue
            elif last_used_state == -1:
                # Door was not used previously, priority to exit
                if exit_queue:
                    next_dir = 1
                else:
                    next_dir = 0
            elif last_used_state == 0:
                # Last used for entering, priority to enter
                if enter_queue:
                    next_dir = 0
                else:
                    next_dir = 1
            else:
                # Last used for exiting, priority to exit
                if exit_queue:
                    next_dir = 1
                else:
                    next_dir = 0

            # Process one person from the chosen direction
            if next_dir == 0:
                idx, _ = heapq.heappop(enter_queue)
                result[idx] = time
                last_used_state = 0
            else:
                idx, _ = heapq.heappop(exit_queue)
                result[idx] = time
                last_used_state = 1

            time += 1

        return result
