from typing import List
import heapq

class Solution:
    def timeTaken(self, arrival: List[int], state: List[int]) -> List[int]:
        n = len(arrival)
        result = [0] * n
        time = 0
        i = 0

        # Priority queues for people waiting to enter or exit
        entry_q = []  # (index, arrival_time)
        exit_q = []   # (index, arrival_time)

        prev_action = -1  # -1 means no previous action

        while i < n or entry_q or exit_q:
            # Add people who have arrived by current time
            while i < n and arrival[i] <= time:
                if state[i] == 0:
                    heapq.heappush(entry_q, (i, arrival[i]))
                else:
                    heapq.heappush(exit_q, (i, arrival[i]))
                i += 1

            # Determine which queue gets priority
            selected = -1

            if not entry_q and not exit_q:
                # No one waiting, move to next arrival
                if i < n:
                    time = arrival[i]
                continue
            elif prev_action == -1:
                # Previous was idle, prioritize exit
                if exit_q:
                    selected = 1
                else:
                    selected = 0
            elif prev_action == 0:
                # Previous was entrance, prioritize entrance
                if entry_q:
                    selected = 0
                else:
                    selected = 1
            else:
                # Previous was exit, prioritize exit
                if exit_q:
                    selected = 1
                else:
                    selected = 0

            # Process one person from selected queue
            if selected == 0:
                idx, _ = heapq.heappop(entry_q)
                result[idx] = time
                prev_action = 0
            else:
                idx, _ = heapq.heappop(exit_q)
                result[idx] = time
                prev_action = 1

            time += 1

