```python
class Solution:
    def maximumTime(self, time: str) -> str:
        time = list(time)
        # Handle hour's first digit
        if time[0] == '?' and time[1] == '?':
            time[0] = '2'
            time[1] = '3'
        elif time[0] == '?':
            time[0] = '2' if time[1] < '4' else '1'
        elif time[1] == '?':
            time[1] = '9' if time[0] == '1' else '3'

        # Handle minute's first digit
        if time[3] == '?':
            time[3] = '5'
        if time[4] == '?':
            time[4] = '9'

        return ''.join(time)
