class Solution:
    def maximumTime(self, time: str) -> str:
        s = list(time)

        if s[0] == '?' and s[1] == '?':
            s[0] = '2'
            s[1] = '3'
        elif s[0] == '?':
            if s[1] in ('0', '1', '2'):
                s[0] = '2'
            else:
                s[0] = '1'
        elif s[1] == '?':
            if s[0] in ('0', '1'):
                s[1] = '9'
            else:
                s[1] = '3'

        if s[3] == '?':
            s[3] = '5'
        if s[4] == '?':
            s[4] = '9'

        return ''.join(s)

