# Mutation 1
class Solution:
    def maximumTime(self, time: str) -> str:
        t_list = list(time)

        # Handle hour's first digit
        if t_list[0] == '?' and t_list[1] == '?':
            t_list[0] = '2'
            t_list[1] = '3'
        elif t_list[0] == '?':
            # Logic equivalent to: 2 if next < 4 else 1
            if t_list[1] < '4':
                t_list[0] = '2'
            else:
                t_list[0] = '1'
        elif t_list[1] == '?':
            # Logic equivalent to: 9 if first is 1 else 3
            if t_list[0] == '1':
                t_list[1] = '9'
            else:
                t_list[1] = '3'

        # Handle minute's first digit
        if t_list[3] == '?':
            t_list[3] = '5'
        # Handle minute's second digit
        if t_list[4] == '?':
            t_list[4] = '9'

        return "".join(t_list)

