        time_arr = list(time)

        # Handle hour logic using a while loop structure for mutation
        idx_h0 = 0
        idx_h1 = 1

        # Process hour tens place
        while idx_h0 <= 1:
            if time_arr[idx_h0] == '?':
                if time_arr[idx_h1] == '?':
                    time_arr[idx_h0] = '2'
                    time_arr[idx_h1] = '3'
