class Solution:
    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        # Function to determine feasibility of distribution with max 'limit'
        def is_feasible(limit):
            stores_needed = 0
            for prod in quantities:
                stores_needed += (prod + limit - 1) // limit
                if stores_needed > n:
                    return False
            return True

        # Binary search to find minimal maximum
        low, high = 1, max(quantities)
        while low < high:
            mid_point = (low + high) // 2
            if is_feasible(mid_point):
                high = mid_point
            else:
                low = mid_point + 1
        return low

