    def sumPrefixScores(self, words: List[str]) -> List[int]:
        from collections import defaultdict

        prefix_counts = defaultdict(int)

        # First pass: count how many times each prefix appears across all words
        for word in words:
            idx = 1
            while idx <= len(word):
                sub = word[:idx]
                prefix_counts[sub] += 1
                idx += 1

        # Second pass: for each word, sum the counts of all its prefixes
        result = []
        for word in words:
            current_sum = 0
            idx = 1
            while idx <= len(word):
                sub = word[:idx]
                current_sum += prefix_counts[sub]
                idx += 1
            result.append(current_sum)

        return result

