class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        from collections import defaultdict

        def build_prefix_map(words_list):
            counts = defaultdict(int)
            for w in words_list:
                for i in range(1, len(w) + 1):
                    counts[w[:i]] += 1
            return counts

        def compute_word_score(word, counts):
            total = 0
            for i in range(1, len(word) + 1):
                total += counts[word[:i]]
            return total

        prefix_count = build_prefix_map(words)
        result = [compute_word_score(w, prefix_count) for w in words]

        return result

