class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        from collections import defaultdict

        # Use a Trie-like structure to store counts at each node
        class TrieNode:
            def __init__(self):
                self.children = {}
                self.count = 0

        root = TrieNode()

        # Insert all words into the trie and increment counts along the path
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
                node.count += 1

        # For each word, traverse the trie again to sum up the scores of all prefixes
        result = []
        for word in words:
            score = 0
            node = root
            for char in word:
                node = node.children[char]
                score += node.count
            result.append(score)

        return result

