class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        prefix_counts = {}

        # First pass: count how many times each prefix appears across all words
        for word in words:
            current_prefix = ""
            for char in word:
                current_prefix += char
                if current_prefix in prefix_counts:
                    prefix_counts[current_prefix] += 1
                else:
                    prefix_counts[current_prefix] = 1

