class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        from collections import defaultdict

        class TrieNode:
            def __init__(self):
                self.children = {}
                self.count = 0

        root = TrieNode()

        # Insert all words into the trie and increment counts along the path
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
                node.count += 1

        result = []
        for word in words:
            score = 0
            node = root
            for char in word:
                node = node.children[char]
                score += node.count
            result.append(score)

        return result

