class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        from collections import deque

        m, n = len(mat), len(mat[0])

        # Convert matrix to a bitmask for easy state representation
        def matrix_to_state(matrix):
            state = 0
            for i in range(m):
                for j in range(n):
                    if matrix[i][j]:
                        state |= 1 << (i * n + j)
            return state

        # Apply flip operation on cell (i,j) and its neighbors
        def get_next_states(state):
            next_states = []
            for i in range(m):
                for j in range(n):
                    flip_mask = 0
                    for dx, dy in [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < m and 0 <= nj < n:
                            flip_mask |= 1 << (ni * n + nj)
                    next_states.append(state ^ flip_mask)
            return next_states

        target = 0
        initial_state = matrix_to_state(mat)

        if initial_state == target:
            return 0

        queue = deque([initial_state])
        visited = set([initial_state])

        steps = 0

        while queue:
            for _ in range(len(queue)):
                current = queue.popleft()
                for next_state in get_next_states(current):
                    if next_state == target:
                        return steps + 1
                    if next_state not in visited:
                        visited.add(next_state)
                        queue.append(next_state)
            steps += 1

        return -1
