class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        from collections import deque

        rows = len(mat)
        cols = len(mat[0])

        # Convert matrix to a bitmask for easy state representation
        def encode_matrix(matrix):
            val = 0
            r = 0
            while r < rows:
                c = 0
                while c < cols:
                    if matrix[r][c]:
                        val |= 1 << (r * cols + c)
                    c += 1
                r += 1
            return val

        # Apply flip operation on cell (i,j) and its neighbors
        def get_flipped_states(state):
            results = []
            r = 0
            while r < rows:
                c = 0
                while c < cols:
                    mask = 0
                    for dr, dc in [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            mask |= 1 << (nr * cols + nc)
                    results.append(state ^ mask)
                    c += 1
                r += 1
            return results

        target_state = 0
        start_state = encode_matrix(mat)

        if start_state == target_state:
            return 0

        q = deque([start_state])
        seen = {start_state}

        dist = 0

        while q:
            size = len(q)
            for _ in range(size):
                curr = q.popleft()
                for nxt in get_flipped_states(curr):
                    if nxt == target_state:
                        return dist + 1
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append(nxt)
            dist += 1

        return -1

