class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        time = 0

        # At each step, we remove first k characters and add any k characters.
        # After t steps, the prefix of length k*t must match the suffix of length k*t for the word to return to original state.

        for t in range(0, n // k + 1):
            removed_chars = t * k
