from typing import List

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        # Algorithm/Data-Structure Variant: Instead of using the built-in sort with a lambda key,
        # we manually implement a counting sort approach based on the number of bits.
        # Constraints: 0 <= arr[i] <= 10^4. Max bits for 10000 is roughly 14 (since 2^13=8192, 2^14=16384).
        # So we can bucket by bit count.

        max_bits = 15
        buckets = [[] for _ in range(max_bits)]

        for num in arr:
            bit_count = bin(num).count('1')
            buckets[bit_count].append(num)

        result = []
        for bucket in buckets:
            # Each bucket needs to be sorted by value (ascending)
            bucket.sort()
            result.extend(bucket)

        return result

