from typing import List

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        # Meaning-Preserving Rewrite: Rename variables, use explicit loop for sorting logic simulation?
        # No, let's stick to the structure but rename everything and change the boolean check style if any.
        # Since the base solution is very concise, let's expand it into a function-based helper and use 'not' equivalent logic where applicable?
        # Actually, let's convert the lambda to a named function and use a different way to get bit count (loop instead of bin().count()).

        def count_set_bits(n):
            count = 0
            while n:
                count += n & 1
                n >>= 1
            return count

        def sort_key(num):
            return (count_set_bits(num), num)

        return sorted(arr, key=sort_key)

