class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        top = [0] * n
        bot = [0] * n

        # Handle columns with sum 2 first
        for idx in range(n):
            if colsum[idx] == 2:
                top[idx] = 1
                bot[idx] = 1
                upper -= 1
                lower -= 1

        # Check validity after processing 2s
        if upper < 0 or lower < 0:
            return []

        # Fill remaining 1s
        for idx in range(n):
            if colsum[idx] == 1:
                if upper > 0:
                    top[idx] = 1
                    upper -= 1
                elif lower > 0:
                    bot[idx] = 1
                    lower -= 1
                else:
                    return []

        # Final check
        if upper != 0 or lower != 0:
            return []

        return [top, bot]

