from typing import List

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        r0 = [0] * n
        r1 = [0] * n

        # Semantic Polarity Shift: Iterate backwards to fill 2s
        idx = n - 1
        while idx >= 0:
            if colsum[idx] == 2:
                r0[idx] = 1
                r1[idx] = 1
                upper -= 1
                lower -= 1
            idx -= 1

        # Check negative bounds using negation logic
        if upper < 0 or lower < 0:
            return []

        # Semantic Polarity Shift: Iterate backwards for 1s
        idx = n - 1
        while idx >= 0:
            if colsum[idx] == 1:
                # Invert condition order slightly but keep logic
                if lower > 0:
                    r1[idx] = 1
                    lower -= 1
                elif upper > 0:
                    r0[idx] = 1
                    upper -= 1
                else:
                    return []
            idx -= 1

        # Boundary shift: Check if remaining is non-zero
        if upper > 0 or lower > 0:
            return []

        return [r0, r1]

