class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        res = [[0] * n, [0] * n]

        # Helper function to process a column
        def assign_one(idx: int, row_idx: int):
            res[row_idx][idx] = 1

        # Process 2s
        ones_needed = []
        for i, val in enumerate(colsum):
            if val == 2:
                assign_one(i, 0)
                assign_one(i, 1)
                upper -= 1
                lower -= 1
            elif val == 1:
                ones_needed.append(i)

        if upper < 0 or lower < 0:
            return []

        # Distribute 1s
        for i in ones_needed:
            if upper > 0:
                assign_one(i, 0)
                upper -= 1
            elif lower > 0:
                assign_one(i, 1)
                lower -= 1
            else:
                return []

        if upper != 0 or lower != 0:
            return []

        return res

