class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        # Data Structure Variant: Use a list of indices instead of direct array filling initially
        twos = []
        ones = []

        for i in range(n):
            if colsum[i] == 2:
                twos.append(i)
            elif colsum[i] == 1:
                ones.append(i)

        # Initialize result matrix
        ans = [[0]*n, [0]*n]

        # Fill 2s
        for i in twos:
            ans[0][i] = 1
            ans[1][i] = 1
            upper -= 1
            lower -= 1

        if upper < 0 or lower < 0:
            return []

        # Fill 1s greedily into upper first
        for i in ones:
            if upper > 0:
                ans[0][i] = 1
                upper -= 1
            else:
                ans[1][i] = 1
                lower -= 1

        # Check if we ran out of capacity mid-way or at end
        if lower < 0 or upper != 0 or lower != 0:
            return []

        return ans

