class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        parent = list(range(n + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX == rootY:
                return False
            parent[rootY] = rootX
            return True

        # Sort by cost ascending to find Minimum Spanning Tree (MST)
        connections.sort(key=lambda x: x[2])

        total_cost = 0
        edges_used = 0

        for u, v, cost in connections:
            if union(u, v):
                total_cost += cost
                edges_used += 1
                if edges_used == n - 1:
                    break

        # Check if all cities are connected
        roots = set()
        for i in range(1, n + 1):
            roots.add(find(i))

        if len(roots) == 1:
            return total_cost
        else:
            return -1

