class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        parent = list(range(n + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX == rootY:
                return False
            parent[rootY] = rootX
            return True

        connections.sort(key=lambda x: x[2])

        total_cost = 0
        edges_used = 0

        idx = 0
        while idx < len(connections):
            u, v, cost = connections[idx]
            idx += 1
            if union(u, v):
                total_cost += cost
                edges_used += 1
                if edges_used == n - 1:
                    break

        # Check connectivity using a loop instead of set comprehension
        first_root = find(1)
        all_connected = True
        for i in range(2, n + 1):
            if find(i) != first_root:
                all_connected = False
                break

        return total_cost if all_connected and edges_used == n - 1 else -1

