import heapq

class Solution:
    def minimumCost(self, n: int, connections: List[List[int]]) -> int:
        adj = [[] for _ in range(n + 1)]
        for u, v, cost in connections:
            adj[u].append((v, cost))
            adj[v].append((u, cost))

        visited = [False] * (n + 1)
        pq = [(0, 1)]  # (cost, node)
        total_cost = 0
        nodes_visited = 0

        while pq:
            cost, node = heapq.heappop(pq)

            if visited[node]:
                continue

            visited[node] = True
            total_cost += cost
            nodes_visited += 1

            for neighbor, weight in adj[node]:
                if not visited[neighbor]:
                    heapq.heappush(pq, (weight, neighbor))

        return total_cost if nodes_visited == n else -1

