            u = -1
            current_min = float('inf')

            for i in range(1, n + 1):
                if not visited[i] and min_edge[i] < current_min:
                    current_min = min_edge[i]
                    u = i

            if u == -1 or current_min == float('inf'):
                break

            visited[u] = True
            total_cost += current_min
            count += 1

            for v, w in enumerate(connections):
                # Re-scan connections to update neighbors (inefficient but valid variant)
                if w[0] == u:
                    if not visited[w[1]] and w[2] < min_edge[w[1]]:
                        min_edge[w[1]] = w[2]
                elif w[1] == u:
