class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        n = len(nums)
        # dp[i][j] will store the length of the longest subsequence ending at nums[i] with j differences
        # We use a dictionary of dictionaries to optimize space
        dp = [defaultdict(int) for _ in range(n)]

        max_len = 0

        for i in range(n):
            num = nums[i]
            # Initialize with 1 (subsequence containing only nums[i])
            dp[i][0] = 1
            for j in range(i):
                prev_num = nums[j]
                if prev_num != num:
                    for diff in range(k):
                        if diff + 1 <= k:
                            dp[i][diff + 1] = max(dp[i][diff + 1], dp[j][diff] + 1)
                else:
                    for diff in range(k + 1):
                        dp[i][diff] = max(dp[i][diff], dp[j][diff] + 1)
            # Update the maximum length found so far
            for diff in dp[i]:
                max_len = max(max_len, dp[i][diff])

        return max_len
