class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        n = len(nums)
        if n == 0:
            return 0

        # dp[i][d] stores the max length of a good subsequence ending at index i with exactly d differences
        dp = [defaultdict(int) for _ in range(n)]
        max_len = 1

        for i in range(n):
            val = nums[i]
            dp[i][0] = 1

            for j in range(i):
                prev_val = nums[j]
                for d in range(k + 1):
                    current_len = dp[j][d]
                    if current_len == 0:
                        continue

                    if prev_val == val:
                        # No new difference added
                        if d <= k:
                            dp[i][d] = max(dp[i][d], current_len + 1)
                    else:
                        # New difference added
                        if d + 1 <= k:
                            dp[i][d + 1] = max(dp[i][d + 1], current_len + 1)

            for d in dp[i]:
                max_len = max(max_len, dp[i][d])

        return max_len

