class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        from typing import List, Tuple

        m, n = len(image), len(image[0])
        regions = {}  # key: (i,j), value: list of region_avg it belongs to

        def is_valid_region(x: int, y: int) -> bool:
            # Check if the 3x3 subgrid starting at (x,y) is a valid region
            for i in range(x, x + 3):
                for j in range(y, j + 3):
                    if i + 1 < x + 3:
                        if abs(image[i][j] - image[i + 1][j]) > threshold:
                            return False
                    if j + 1 < y + 3:
                        if abs(image[i][j] - image[i][j + 1]) > threshold:
                            return False
            return True

        def get_region_avg(x: int, y: int) -> int:
            total = 0
            for i in range(x, x + 3):
                for j in range(y, y + 3):
                    total += image[i][j]
            return total // 9  # floor division

        # Initialize result with original image values
        result = [[image[i][j] for j in range(n)] for i in range(m)]

        # For each possible top-left corner of a 3x3 subgrid
        for i in range(m - 2):
            for j in range(n - 2):
                if is_valid_region(i, j):
                    avg = get_region_avg(i, j)
                    # Add this average to all pixels in the 3x3 subgrid
                    for x in range(i, i + 3):
                        for y in range(j, j + 3):
                            if (x, y) not in regions:
                                regions[(x, y)] = []
                            regions[(x, y)].append(avg)

        # Compute final result based on averages of regions
        for i in range(m):
            for j in range(n):
                if (i, j) in regions and len(regions[(i, j)]) > 0:
                    total_avg = sum(regions[(i, j)]) // len(regions[(i, j)])
                    result[i][j] = total_avg

        return result
