class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        from typing import List

        R, C = len(image), len(image[0])
        # Store lists of rounded averages for each pixel
        pixel_data = {}

        def verify_block(tr: int, tc: int) -> bool:
            # Check all adjacent pairs in the 3x3 block
            # Iterate over rows 0 to 1 and cols 0 to 2 for vertical checks
            # Iterate over rows 0 to 2 and cols 0 to 1 for horizontal checks
            # The block is defined by top-left (tr, tc) covering [tr..tr+2][tc..tc+2]

            # Check vertical neighbors (row i, col j vs row i+1, col j)
            for i in range(tr, tr + 2):
                for j in range(tc, tc + 3):
                    if abs(image[i][j] - image[i + 1][j]) > threshold:
                        return False

            # Check horizontal neighbors (row i, col j vs row i, col j+1)
            for i in range(tr, tr + 3):
                for j in range(tc, tc + 2):
                    if abs(image[i][j] - image[i][j + 1]) > threshold:
                        return False

            return True

        def get_avg(r: int, c: int) -> int:
            s = 0
            for i in range(r, r + 3):
                for j in range(c, c + 3):
                    s += image[i][j]
            return s // 9

        res = [[image[i][j] for j in range(C)] for i in range(R)]

        # Iterate through the grid
        for i in range(R - 2):
            for j in range(C - 2):
                if verify_block(i, j):
                    avg = get_avg(i, j)
                    for x in range(i, i + 3):
                        for y in range(j, j + 3):
                            if (x, y) not in pixel_data:
                                pixel_data[(x, y)] = []
                            pixel_data[(x, y)].append(avg)

        for i in range(R):
            for j in range(C):
                if (i, j) in pixel_data and len(pixel_data[(i, j)]) > 0:
                    vals = pixel_data[(i, j)]
                    res[i][j] = sum(vals) // len(vals)

        return res

