class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        # Use a dictionary to accumulate averages for each pixel
        accumulators = {}

        # Helper to validate a 3x3 region
        def is_region_ok(start_r: int, start_c: int) -> bool:
            r, c = start_r, start_c
            while r < start_r + 3:
                c_inner = c
                while c_inner < start_c + 3:
                    curr = image[r][c_inner]
                    # Check horizontal neighbor
                    if c_inner + 1 < start_c + 3:
                        if abs(curr - image[r][c_inner + 1]) > threshold:
                            return False
                    # Check vertical neighbor
                    if r + 1 < start_r + 3:
                        if abs(curr - image[r + 1][c_inner]) > threshold:
                            return False
                    c_inner += 1
                r += 1
            return True

        # Helper to calculate floor average of a 3x3 region
        def calc_avg(sr: int, sc: int) -> int:
            total_sum = 0
            idx_r = sr
            while idx_r < sr + 3:
                idx_c = sc
                while idx_c < sc + 3:
                    total_sum += image[idx_r][idx_c]
                    idx_c += 1
                idx_r += 1
            return total_sum // 9

        # Prepare result grid initialized with input
        final_res = [row[:] for row in image]

        # Scan all possible top-left positions using while loops
        r_start = 0
        while r_start <= m - 3:
            c_start = 0
            while c_start <= n - 3:
                if is_region_ok(r_start, c_start):
                    avg_val = calc_avg(r_start, c_start)
                    # Update neighbors
                    nr = r_start
                    while nr < r_start + 3:
                        nc = c_start
                        while nc < c_start + 3:
                            if (nr, nc) not in accumulators:
                                accumulators[(nr, nc)] = []
                            accumulators[(nr, nc)].append(avg_val)
                            nc += 1
                        nr += 1
                c_start += 1
            r_start += 1

        # Apply accumulated averages
        for r in range(m):
            for c in range(n):
                if (r, c) in accumulators:
                    counts = accumulators[(r, c)]
                    if counts:
                        final_res[r][c] = sum(counts) // len(counts)

        return final_res

