            # Check all adjacent pairs in the 3x3 block
            # Iterate over rows 0 to 1 and cols 0 to 2 for vertical checks
            # Iterate over rows 0 to 2 and cols 0 to 1 for horizontal checks
            # The block is defined by top-left (tr, tc) covering [tr..tr+2][tc..tc+2]

            # Check vertical neighbors (row i, col j vs row i+1, col j)
            for i in range(tr, tr + 2):
                for j in range(tc, tc + 3):
                    if abs(image[i][j] - image[i + 1][j]) > threshold:
                        return False

            # Check horizontal neighbors (row i, col j vs row i, col j+1)
            for i in range(tr, tr + 3):
                for j in range(tc, tc + 2):
                    if abs(image[i][j] - image[i][j + 1]) > threshold:
                        return False

            return True

        def get_avg(r: int, c: int) -> int:
