class Solution:
    def hasPath(self, maze: List[List[int]], start: List[int], destination: List[int]) -> bool:
        m, n = len(maze), len(maze[0])
        visited = set()

        def roll(x, y):
            # Helper function to simulate rolling
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x, y
                while 0 <= nx + dx < m and 0 <= ny + dy < n and maze[nx + dx][ny + dy] == 0:
                    nx += dx
                    ny += dy
                yield (nx, ny)

        stack = [tuple(start)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))

            if cx == destination[0] and cy == destination[1]:
                return True

            for nx, ny in roll(cx, cy):
                if (nx, ny) not in visited:
                    stack.append((nx, ny))
        return False

