        stack = [start]

        while stack:
            curr = stack.pop()
            r, c = curr[0], curr[1]

            if r == destination[0] and c == destination[1]:
                return True

            if visited[r][c]:
                continue
            visited[r][c] = True

            # Directions: up, down, left, right
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
