                # Roll until hitting a wall
                while 0 <= nr + dr < m and 0 <= nc + dc < n and maze[nr + dr][nc + dc] == 0:
                    nr += dr
                    nc += dc

                if not visited[nr][nc]:
                    stack.append([nr, nc])

