class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        left = 0
        max_length = 0
        zero_count = 0
        n = len(nums)

        right = 0
        while right < n:
            if nums[right] == 0:
                zero_count += 1

            # Shrink window if it contains more than k zeros
            while zero_count > k:
                if nums[left] == 0:
                    zero_count -= 1
                left += 1

            # Update max length with the current valid window size
            current_len = right - left + 1
            if current_len > max_length:
                max_length = current_len

            right += 1

        return max_length

