from typing import List
from collections import deque

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        zero_indices = deque()
        left = 0
        max_length = 0

        for right in range(len(nums)):
            if nums[right] == 0:
                zero_indices.append(right)

            if len(zero_indices) > k:
                # The window should start just after the oldest zero (the one we are removing)
                # However, the logic here sets 'left' to the index of the removed zero + 1.
                # But wait, if we remove a zero from the window, the new window starts at left + 1?
                # No, the standard sliding window approach with a deque of zeros:
                # When len(zero_indices) > k, we need to shrink the window from the left until we exclude one zero.
                # The zero we are excluding is zero_indices[0]. So the new left should be zero_indices[0] + 1.
                # This effectively removes that zero from our count of allowed flips.

                left = zero_indices.popleft() + 1

            # Current window is [left, right]
            current_length = right - left + 1
            if current_length > max_length:
                max_length = current_length

        return max_length

