# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
from typing import Optional

class Solution:
    def maxAncestorDiff(self, root: Optional[TreeNode]) -> int:
        def traverse(current_node, minimum_val, maximum_val):
            if current_node is None:
                return 0

            new_min = min(minimum_val, current_node.val)
            new_max = max(maximum_val, current_node.val)

            diff = max(abs(new_max - current_node.val), abs(new_min - current_node.val))

            res_left = traverse(current_node.left, new_min, new_max)
            res_right = traverse(current_node.right, new_min, new_max)

            return max(diff, res_left, res_right)

        return traverse(root, root.val, root.val)

