class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        stack_count = 0
        insertions = 0

        for char in s:
            if char == '(':
                stack_count += 1
            elif char == ')':
                if stack_count > 0:
                    stack_count -= 1
                else:
                    insertions += 1

        return insertions + stack_count

