class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Build adjacency list
        adj = defaultdict(list)
        for u, v, w in highways:
            adj[u].append((v, w))
            adj[v].append((u, w))

        best_cost = -1

        # Since n is small (<= 15), we can use DFS with backtracking to find all valid paths of length k
        # A path of k highways visits k+1 cities.

        def dfs(current_city, visited, steps, current_cost):
            nonlocal best_cost
            if steps == k:
                best_cost = max(best_cost, current_cost)
                return

            for neighbor, weight in adj[current_city]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    dfs(neighbor, visited, steps + 1, current_cost + weight)
                    visited.remove(neighbor)

        # Try starting from each city
        for start in range(n):
            visited = {start}
            dfs(start, visited, 0, 0)

        return best_cost

