class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Build adjacency list
        graph = defaultdict(list)
        for city1, city2, toll in highways:
            graph[city1].append((city2, toll))
            graph[city2].append((city1, toll))

        max_cost = -1

        # Use DFS to find all paths of exactly k edges (k+1 cities)
        # Since n is small (<= 15), we can use backtracking
        visited = [False] * n

        def dfs(city, steps, current_cost):
            nonlocal max_cost
            if steps == k:
                max_cost = max(max_cost, current_cost)
                return

            for neighbor, toll in graph[city]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    dfs(neighbor, steps + 1, current_cost + toll)
                    visited[neighbor] = False

        # Try starting from each city
        for start_city in range(n):
            visited[start_city] = True
            dfs(start_city, 0, 0)
            visited[start_city] = False

        return max_cost

