class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Build adjacency list
        graph = defaultdict(list)
        for city1, city2, toll in highways:
            graph[city1].append((city2, toll))
            graph[city2].append((city1, toll))

        max_cost = -1

        # We need to find a path of exactly k edges (k+1 cities) with no repeated cities.
        # Since n is small (<= 15), we can use DFS/backtracking.
        # Using permutations of all cities is too slow if k is large and n is up to 15.
        # Instead, we iterate through each starting city and perform DFS.

        def dfs(current_city: int, visited: set, depth: int, current_cost: int):
            nonlocal max_cost
            if depth == k:
                max_cost = max(max_cost, current_cost)
                return

            for neighbor, cost in graph[current_city]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    dfs(neighbor, visited, depth + 1, current_cost + cost)
                    visited.remove(neighbor)

        # Try starting from each city
        for start_node in range(n):
            visited = {start_node}
            dfs(start_node, visited, 0, 0)

        return max_cost

