from typing import List

class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        dist_squared = lambda pt: pt[0] * pt[0] + pt[1] * pt[1]
        points.sort(key=dist_squared)
        return points[:k]

