from typing import List

class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        def calc_dist_sq(p):
            return p[0]**2 + p[1]**2

        res = []
        temp_points = list(points)

        for _ in range(k):
            if not temp_points:
                break
            closest_idx = 0
            min_val = calc_dist_sq(temp_points[0])
            for i in range(1, len(temp_points)):
                d = calc_dist_sq(temp_points[i])
                if d < min_val:
                    min_val = d
                    closest_idx = i
            res.append(temp_points.pop(closest_idx))

        return res

