class Solution:
    def sumNumbers(self, root: Optional['TreeNode']) -> int:
        if not root:
            return 0

        total = 0
        stack = [(root, root.val)]

        while stack:
            node, current_val = stack.pop()

            # If it's a leaf node, add the accumulated value to total
            if not node.left and not node.right:
                total += current_val

            # Push children to stack with updated values
