class Solution:
    def minMaxDifference(self, num: int) -> int:
        num_str = str(num)

        # To get the maximum value, replace the first non-9 digit with 9
        for d in num_str:
            if d != '9':
                max_val = int(num_str.replace(d, '9'))
                break
        else:
            max_val = num  # All digits are 9

        # To get the minimum value, replace the first non-0 digit with 0
        for d in num_str:
            if d != '0':
                min_val = int(num_str.replace(d, '0'))
                break
        else:
            min_val = num  # All digits are 0

        return max_val - min_val
