class Solution:
    def minMaxDifference(self, num: int) -> int:
        s = str(num)

        # Helper to calculate value after replacement
        def get_replaced_value(original_str, from_char, to_char):
            result_list = []
            for ch in original_str:
                if ch == from_char:
                    result_list.append(to_char)
                else:
                    result_list.append(ch)
            return int("".join(result_list))

        # Find digit to maximize (first non-9)
        d_to_max = None
        idx = 0
        while idx < len(s):
            if s[idx] != '9':
                d_to_max = s[idx]
                break
            idx += 1

        if d_to_max is not None:
            max_val = get_replaced_value(s, d_to_max, '9')
        else:
            max_val = num

        # Find digit to minimize (first non-0)
        d_to_min = None
        idx = 0
        while idx < len(s):
            if s[idx] != '0':
                d_to_min = s[idx]
                break
            idx += 1

        if d_to_min is not None:
            min_val = get_replaced_value(s, d_to_min, '0')
        else:
            min_val = num

        return max_val - min_val

