class Solution:
    def countCharacters(self, words: List[str], chars: str) -> int:
        chars_counter = Counter(chars)
        total_length = 0

        for word in words:
            word_counter = Counter(word)
            if all(word_counter[c] <= chars_counter[c] for c in word_counter):
                total_length += len(word)

        return total_length
