from typing import List

class Solution:
    def minScoreTriangulation(self, values: List[int]) -> int:
        n = len(values)
        # Create DP table initialized with 0
        dp = [[0] * n for _ in range(n)]

        # Iterate over the length of the chain (number of vertices involved in the subproblem)
        # We need at least 3 vertices to form a triangle, so length starts from 2 (indices i to i+2)
        for length in range(2, n):
            for i in range(n - length):
                j = i + length
                dp[i][j] = float('inf')
                # Try every possible vertex k between i and j as the third vertex of the triangle
                # The triangle is formed by vertices i, k, j.
                # The cost is the product of their values plus the optimal scores for the two resulting polygons.
                for k in range(i + 1, j):
                    cost = dp[i][k] + dp[k][j] + values[i] * values[k] * values[j]
                    if cost < dp[i][j]:
                        dp[i][j] = cost

        return dp[0][n - 1]

