from typing import List
from collections import defaultdict

class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        remainder_map = defaultdict(int)
        result = 0

        for current_hour in hours:
            mod_val = current_hour % 24
            needed_mod = (24 - mod_val) % 24

            if needed_mod in remainder_map:
                result += remainder_map[needed_mod]

            remainder_map[mod_val] += 1

        return result

