class Solution:
    def simulationResult(self, windows: List[int], queries: List[int]) -> List[int]:
        # Use a deque for efficient O(1) operations at both ends
        from collections import deque

        dq = deque(windows)

        for q in queries:
            if q in dq:
                dq.remove(q)
            dq.appendleft(q)

        return list(dq)

