class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        n = len(image[0])

        def has_black_in_row(start, end):
            for r in range(start, end + 1):
                if '1' in image[r]:
                    return True
            return False

        def has_black_in_col(start, end):
            for c in range(start, end + 1):
                for r in range(m):
                    if image[r][c] == '1':
                        return True
            return False

        def find_top():
            lo, hi = 0, x
            while lo < hi:
                mid = (lo + hi) // 2
                if has_black_in_row(mid, x):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        def find_bottom():
            lo, hi = x, m - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if has_black_in_row(x, mid):
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        def find_left():
            lo, hi = 0, y
            while lo < hi:
                mid = (lo + hi) // 2
                if has_black_in_col(mid, y):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        def find_right():
            lo, hi = y, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if has_black_in_col(y, mid):
                    lo = mid
                else:
                    hi = mid - 1
            return lo

        top = find_top()
        bottom = find_bottom()
        left = find_left()
        right = find_right()

        return (bottom - top + 1) * (right - left + 1)

