class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        from typing import List

        m = len(image)
        n = len(image[0])

        def pixel_is_black(r, c):
            return image[r][c] == '1'

        def contains_black_in_range(start_idx, end_idx, search_horizontal):
            if search_horizontal:
                for row in range(start_idx, end_idx + 1):
                    for col in range(n):
                        if pixel_is_black(row, col):
                            return True
            else:
                for col in range(start_idx, end_idx + 1):
                    for row in range(m):
                        if pixel_is_black(row, col):
                            return True
            return False

        def find_boundary(low, high, horizontal_search):
            while low < high:
                mid = (low + high) // 2
                if contains_black_in_range(low, mid, horizontal_search):
                    high = mid
                else:
                    low = mid + 1
            return low

        top_bound = find_boundary(0, x, True)
        bottom_bound = find_boundary(x, m - 1, True)
        left_bound = find_boundary(0, y, False)
        right_bound = find_boundary(y, n - 1, False)

        return (bottom_bound - top_bound) * (right_bound - left_bound)

