class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        from typing import List

        m = len(image)
        n = len(image[0])

        def has_pixel(row, col):
            return image[row][col] == '1'

        def check_row_segment(r_start, r_end):
            idx = r_start
            while idx <= r_end:
                for c in range(n):
                    if has_pixel(idx, c):
                        return True
                idx += 1
            return False

        def check_col_segment(c_start, c_end):
            idx = c_start
            while idx <= c_end:
                for r in range(m):
                    if has_pixel(r, idx):
                        return True
                idx += 1
            return False

        def binary_search_vertical(start, end):
            lo, hi = start, end
            while lo < hi:
                mid = (lo + hi) // 2
                if check_row_segment(lo, mid):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        def binary_search_horizontal(start, end):
            lo, hi = start, end
            while lo < hi:
                mid = (lo + hi) // 2
                if check_col_segment(lo, mid):
                    hi = mid
                else:
                    lo = mid + 1
            return lo

        top = binary_search_vertical(0, x)
        bottom = binary_search_vertical(x, m - 1)
