class Solution:
    def convertToBase7(self, num: int) -> str:
        if num == 0:
            return "0"

        negative_flag = False
        if num < 0:
            negative_flag = True
            num = -num

        res_list = []
        while num != 0:
            remainder = num % 7
            res_list.append(str(remainder))
            num = num // 7

        final_str = "".join(res_list[::-1])

        if negative_flag:
            return "-" + final_str
        else:
            return final_str

