class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        def check(t):
            total = 0
            for x in time:
                total += t // x
            return total >= totalTrips

        # Semantic Polarity Shift: Negate condition and swap logic
        left = 1
        right = min(time) * totalTrips

        while left < right:
            mid = (left + right) // 2
            # Inverted logic: if NOT enough trips, move left up; otherwise move right down
            if not check(mid):
                left = mid + 1
            else:
                right = mid

        return left

