class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        # Algorithm/Data-Structure Variant: Use binary search with explicit range bounds
        # Instead of min(time)*totalTrips, we use a safe upper bound derived from constraints
        # though the logic remains binary search on answer.

        def trips_in(t):
            acc = 0
            for b in time:
                acc += t // b
            return acc

        l, r = 1, 10**14  # Sufficiently large upper bound given constraints (max time ~1e7, max trips ~1e7 -> 1e14)

        ans = r

        while l <= r:
            m = (l + r) // 2
            if trips_in(m) >= totalTrips:
                ans = m
                r = m - 1
            else:
                l = m + 1

        return ans

