class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        # Structural Transformation: Extract helper and use recursion (with iterative fallback via stack simulation conceptually, 
        # but here we keep it iterative for Python safety, just restructuring flow)
        # Actually, let's do a recursive binary search as a structural transformation
        def bs(low, high):
            if low >= high:
                return low
            mid = (low + high) // 2
            # Calculate trips
            current_trips = 0
            for t in time:
                current_trips += mid // t

            if current_trips >= totalTrips:
                return bs(low, mid)
            else:
                return bs(mid + 1, high)

        start = 1
        end = min(time) * totalTrips
        return bs(start, end)

