class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        # Helper function to calculate total trips completed by all buses in time `t`
        def trips_completed(t):
            return sum(t // bus_time for bus_time in time)

        # Binary search range:
        # Lower bound: 1 (minimum possible time)
        # Upper bound: min(time) * totalTrips (time taken by the fastest bus to do all trips alone)
        left = 1
        right = min(time) * totalTrips

        while left < right:
            mid = (left + right) // 2
            if trips_completed(mid) >= totalTrips:
                right = mid
            else:
                left = mid + 1

        return left

