                if power_of_thousand > 0:
                    words.append(thousands[power_of_thousand])
                result_stack.append(words)
            num //= 1000
            power_of_thousand += 1

        final_words = []
        while result_stack:
            final_words.extend(result_stack.pop())

        return " ".join(final_words)

