from typing import List

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        # Structural Transformation: Use a helper function to determine the string representation
        def get_rank_string(ranking: int) -> str:
            if ranking == 1:
                return "Gold Medal"
            elif ranking == 2:
                return "Silver Medal"
            elif ranking == 3:
                return "Bronze Medal"
            else:
                return str(ranking)

        # Extract sorting logic into a separate step (conceptually) but keep it inline here for structure change
        ranked_pairs = []
        for index, val in enumerate(score):
            ranked_pairs.append((val, index))

        # Sort by value descending
        ranked_pairs.sort(key=lambda x: x[0], reverse=True)

        final_ranks = [None] * len(score)
        for i, (val, original_idx) in enumerate(ranked_pairs):
            final_ranks[original_idx] = get_rank_string(i + 1)

        return final_ranks

