from typing import List

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        # Semantic Polarity Shift: Negate condition and swap comparison logic
        # Logic inversion: Instead of checking if rank <= 3, we check if rank > 3 to default to number
        # Also changed boundary: range(len(sorted_scores)) vs range(n-1) - though here we iterate all
        # We will invert the boolean check for medals: if not is_medal_rank
        sorted_scores = sorted(score, reverse=True)
        n = len(sorted_scores)
        rank_map = {}

        for i in range(n):
            s = sorted_scores[i]
            rank_val = i + 1

            # Inverted logic: Check if NOT a top 3 rank first
            if not (rank_val <= 3):
                rank_map[s] = str(rank_val)
            else:
                # Handle the specific medals
                if rank_val == 1:
                    rank_map[s] = "Gold Medal"
                elif rank_val == 2:
                    rank_map[s] = "Silver Medal"
                elif rank_val == 3:
                    rank_map[s] = "Bronze Medal"

        return [rank_map[s] for s in score]

