from typing import List
import heapq

class Solution:
    def Algorithm / Data-Structure Variant: Replace sort with Min-Heap approach to simulate max extraction
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        # Create a min-heap of (-score, index) to extract largest scores first
        heap = []
        for i, s in enumerate(score):
            heapq.heappush(heap, (-s, i))

        result = [""] * len(score)
        count = 1

        while heap:
            neg_score, idx = heapq.heappop(heap)
