from typing import List

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        base_sum = sum(nums1)
        rate_sum = sum(nums2)

        indices = list(range(n))
        indices.sort(key=lambda i: nums2[i])  # Sort by nums2 ascending

        dp = [0] * (n + 1)

        for i in range(n):
            a, b = nums1[indices[i]], nums2[indices[i]]
            for t in range(i + 1, 0, -1):
                dp[t] = max(dp[t], dp[t - 1] + a + b * t)

        for t in range(n + 1):
            current_sum = base_sum + t * rate_sum - dp[t]
            if current_sum <= x:
                return t

        return -1

