class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_all_indices(text: str, pattern: str) -> List[int]:
            res = []
            n = len(pattern)
            for i in range(len(text) - n + 1):
                if text[i:i+n] == pattern:
                    res.append(i)
            return res

        a_indices = find_all_indices(s, a)
        b_indices = find_all_indices(s, b)

        # Sort and prepare for binary search
        b_indices.sort()

        result = []
        from bisect import bisect_left

        for i in a_indices:
            # Find the first b index >= i - k
            left = bisect_left(b_indices, i - k)
            # Check if there's any b index within [i - k, i + k]
            for j in range(left, len(b_indices)):
                if abs(b_indices[j] - i) <= k:
                    result.append(i)
                    break
        return result
```

