class Solution:
    def maxSum(self, nums: List[int]) -> int:
        from collections import defaultdict

        # Dictionary to store numbers grouped by their largest digit
        groups_by_max_digit = defaultdict(list)

        for number in nums:
            max_d = max(int(digit) for digit in str(number))
            groups_by_max_digit[max_d].append(number)

