    def maxSum(self, nums: List[int]) -> int:
        from collections import defaultdict

        # Dictionary to store numbers grouped by their largest digit
        digit_groups = defaultdict(list)

        for num in nums:
            max_digit = max(int(d) for d in str(num))
            digit_groups[max_digit].append(num)

        max_sum = -1

        # For each group with the same largest digit, find top two numbers and sum them
        for group in digit_groups.values():
            if len(group) >= 2:
                # Sort descending and take top two
                sorted_group = sorted(group, reverse=True)
                current_sum = sorted_group[0] + sorted_group[1]
                max_sum = max(max_sum, current_sum)

        return max_sum

