    def maxSum(self, nums: List[int]) -> int:
        from collections import defaultdict

        # Dictionary to store the maximum number seen so far for each largest digit
        max_val_per_digit = {}
        max_sum = -1

        for num in nums:
            max_digit = max(int(d) for d in str(num))

            if max_digit in max_val_per_digit:
                prev_max = max_val_per_digit[max_digit]
                current_sum = prev_max + num
                if current_sum > max_sum:
                    max_sum = current_sum

                # Update the stored max value if current is larger
                if num > prev_max:
                    max_val_per_digit[max_digit] = num
            else:
                max_val_per_digit[max_digit] = num

        return max_sum

