        triplet_count = 0
        idx_i = 0
        while idx_i < total_elements:
            idx_j = idx_i + 1
            while idx_j < total_elements:
                idx_k = idx_j + 1
                while idx_k < total_elements:
                    if (nums[idx_i] + nums[idx_j] + nums[idx_k]) % d == 0:
                        triplet_count += 1
                    idx_k += 1
                idx_j += 1
            idx_i += 1
        return triplet_count

