from typing import List

class Solution:
    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        def compute_dists(start):
            d = [-1] * len(edges)
            curr = start
            step = 0
            while curr != -1 and d[curr] == -1:
                d[curr] = step
                step += 1
                curr = edges[curr]
            return d

        dist_a = compute_dists(node1)
        dist_b = compute_dists(node2)

        best_val = float('inf')
        ans = -1
        n = len(edges)

        for idx in range(n):
            if dist_a[idx] != -1 and dist_b[idx] != -1:
                cur_max = max(dist_a[idx], dist_b[idx])
                if cur_max < best_val:
                    best_val = cur_max
                    ans = idx
                elif cur_max == best_val:
                    if ans == -1 or idx < ans:
                        ans = idx

        return ans

