class Solution:
    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        def bfs_distances(start):
            n = len(edges)
            dist = [-1] * n
            q = [start]
            dist[start] = 0
            head = 0
            while head < len(q):
                u = q[head]
                head += 1
                v = edges[u]
                if v != -1 and dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
            return dist

        d1 = bfs_distances(node1)
        d2 = bfs_distances(node2)

        min_val = float('inf')
        res = -1
        for i in range(len(edges)):
            if d1[i] != -1 and d2[i] != -1:
                mx = max(d1[i], d2[i])
                if mx < min_val:
                    min_val = mx
                    res = i
                elif mx == min_val and (res == -1 or i < res):
                    res = i
        return res

