from typing import List

class Solution:
    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        def trace_path(start):
            d = {}
            cur = start
            dist = 0
            while cur != -1 and cur not in d:
                d[cur] = dist
                dist += 1
                cur = edges[cur]
            return d

        path1 = trace_path(node1)
        path2 = trace_path(node2)

        candidates = []
        for node in path1:
            if node in path2:
                maxd = max(path1[node], path2[node])
                candidates.append((maxd, node))

        if not candidates:
            return -1

        # Sort by max distance first, then by node index
        candidates.sort(key=lambda x: (x[0], x[1]))
        return candidates[0][1]

