from collections import Counter

class Solution:
    def minCost(self, basket1: list[int], basket2: list[int]) -> int:
        count1 = Counter(basket1)
        count2 = Counter(basket2)

        combined = count1 + count2

        for cost, freq in combined.items():
            if freq % 2 != 0:
                return -1

        target = {cost: freq // 2 for cost, freq in combined.items()}

        surplus1 = []
        surplus2 = []

        all_fruits = sorted(set(count1.keys()) | set(count2.keys()))

        for fruit in all_fruits:
            cnt1 = count1.get(fruit, 0)
            cnt2 = count2.get(fruit, 0)
            needed = target[fruit]

            if cnt1 > needed:
                surplus1.extend([fruit] * (cnt1 - needed))
            elif cnt1 < needed:
                surplus2.extend([fruit] * (needed - cnt1))

        if len(surplus1) != len(surplus2):
            return -1

        min_val = min(combined.keys())

        total_cost = 0
        for f1, f2 in zip(surplus1, surplus2):
            swap_cost = min(f1, f2)
            total_cost += swap_cost

            if swap_cost == min_val:
                continue

            min_swap_cost = min_val
            total_cost += min_swap_cost

        return total_cost

