    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        if not root:
            return None

        parent_map = {root: None}
        queue = [root]

        # BFS to populate parent pointers until both p and q are found
        while p not in parent_map or q not in parent_map:
            if not queue:
                break
            node = queue.pop(0)
            if node.left:
                parent_map[node.left] = node
                queue.append(node.left)
            if node.right:
                parent_map[node.right] = node
                queue.append(node.right)

        # If either was not found in the map, handle gracefully
        if p not in parent_map or q not in parent_map:
            return None

        # Build path from p to root
