from typing import List

class Solution:
    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:
        if len(arr) <= 2:
            return True

        min_val = min(arr)
        max_val = max(arr)

        # Check if (max - min) is divisible by (n - 1)
        if (max_val - min_val) % (len(arr) - 1) != 0:
            return False

        step = (max_val - min_val) // (len(arr) - 1)

        if step == 0:
            # All elements must be equal
            return len(set(arr)) == 1

        seen = set(arr)
        # Verify that every expected element exists
        for i in range(len(arr)):
            expected = min_val + i * step
            if expected not in seen:
                return False

        return True

