class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        answer = [[0] * n for _ in range(m)]

        def get_diagonal_count(r, c, direction):
            values = set()
            i, j = r + direction, c + direction
            while 0 <= i < m and 0 <= j < n:
                values.add(grid[i][j])
                i += direction
                j += direction
            return len(values)

        for r in range(m):
            for c in range(n):
                left_above = get_diagonal_count(r, c, -1)
                right_below = get_diagonal_count(r, c, 1)
                answer[r][c] = abs(left_above - right_below)

        return answer

