class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        rows, cols = len(grid), len(grid[0])
        result = [[0] * cols for _ in range(rows)]

        for row in range(rows):
            for col in range(cols):
                upper_left = set()
                x, y = row - 1, col - 1
                while x >= 0 and y >= 0:
                    upper_left.add(grid[x][y])
                    x -= 1
                    y -= 1

                lower_right = set()
                x, y = row + 1, col + 1
                while x < rows and y < cols:
                    lower_right.add(grid[x][y])
                    x += 1
                    y += 1

                result[row][col] = abs(len(upper_left) - len(lower_right))

        return result

