class Solution:
    def differenceOfDistinctValues(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        result = [[0]*n for _ in range(m)]

        def count_left_diagonal(r, c):
            elements = set()
            while r >= 0 and c >= 0:
                elements.add(grid[r][c])
                r -= 1
                c -= 1
            return len(elements)

        def count_right_diagonal(r, c):
            elements = set()
            while r < m and c < n:
                elements.add(grid[r][c])
                r += 1
                c += 1
            return len(elements)

        for i in range(m):
            for j in range(n):
                left = count_left_diagonal(i-1, j-1)
                right = count_right_diagonal(i+1, j+1)
                result[i][j] = abs(left - right)

