from typing import List

class Solution:
    def maximizeGreatness(self, nums: List[int]) -> int:
        sorted_nums = sorted(nums)
        match_count = 0
        ptr = 0
        total_len = len(sorted_nums)

        for val in sorted_nums:
            while ptr < total_len and sorted_nums[ptr] <= val:
                ptr += 1

            if ptr < total_len:
                match_count += 1
                ptr += 1

        return match_count

