class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def locate_occurrences(source: str, target: str) -> List[int]:
            occurrences = []
            t_len = len(target)
            if t_len == 0 or t_len > len(source):
                return occurrences
            for idx in range(len(source) - t_len + 1):
                if source[idx : idx + t_len] == target:
                    occurrences.append(idx)
            return occurrences

        loc_a = locate_occurrences(s, a)
        loc_b = locate_occurrences(s, b)

        # Sort and prepare for binary search (loc_b is already sorted by construction, but explicit sort doesn't hurt)
        loc_b.sort()

        ans = []

        for pos in loc_a:
            # Find the first b index >= pos - k
            start_idx = bisect_left(loc_b, pos - k)

            # Check if there is any b index within [pos - k, pos + k]
            # We only need to check the first candidate found by bisect_left
            if start_idx < len(loc_b) and loc_b[start_idx] <= pos + k:
                ans.append(pos)

        return ans

