class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_matches(text: str, pattern: str) -> List[int]:
            res = []
            n = len(pattern)
            if n > len(text):
                return res
            for i in range(len(text) - n + 1):
                if text[i:i+n] == pattern:
                    res.append(i)
            return res

        a_pos = find_matches(s, a)
        b_pos = find_matches(s, b)

        # Sort and prepare for binary search
        b_pos.sort()

        output = []

        for i in a_pos:
            low_bound = i - k
            high_bound = i + k

            # Find first index >= low_bound
            left = bisect_left(b_pos, low_bound)
            # Find first index > high_bound
            right = bisect_right(b_pos, high_bound)

            # If the range [left, right) is not empty, then we have a match
            if left < right:
                output.append(i)

        return output

