class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        count = 0
        i = 1
        while i * i <= n:
            if n % i == 0:
                count += 1
                if count == k:
                    return i

                # Check the pair factor
                pair = n // i
                if pair != i:
                    count += 1
                    if count == k:
                        return pair

            i += 1

        return -1

