class Solution:
    def kthFactor(self, n: int, k: int) -> int:
        def get_factors(num, idx):
            if idx > num:
                return -1
            if num % idx == 0:
                if k == 1:
                    return idx
                else:
                    res = get_factors(num, idx + 1)
                    if res != -1:
                        return res
                    else:
                        return -1
            else:
                return get_factors(num, idx + 1)

        # Helper wrapper to handle the recursive logic with closure or state
        # Since we can't easily pass 'k' down recursively without changing signature or using nonlocal, 
        # we restructure slightly to match the constraint of preserving signature by using a helper inside.
        # However, to strictly follow "preserve class/function signature" and "complete runnable", 
        # we will use an iterative approach that mimics recursion via a stack or simply re-implement 
        # the logic as a separate helper function defined inside the method.

        # Re-implementation of the recursive logic within the method scope
        def recurse(current, remaining_k):
            if current > n:
                return -1
            if n % current == 0:
                if remaining_k == 1:
                    return current
                res = recurse(current + 1, remaining_k - 1)
                if res != -1:
                    return res
            return recurse(current + 1, remaining_k)

        return recurse(1, k)

