class Solution:
    def countPairs(self, root: 'Optional[TreeNode]', distance: int) -> int:
        self.count_good = 0

        def traverse(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [1]

            dists_left = traverse(node.left)
            dists_right = traverse(node.right)

            # Count good pairs between leaves in left and right subtrees
            for dl in dists_left:
                for dr in dists_right:
                    if dl + dr <= distance:
                        self.count_good += 1

            # Add 1 to all distances to propagate up one level
            # Only keep distances that are less than or equal to distance, 
            # as any path longer than distance cannot form a valid pair further up.
            new_dists = [d + 1 for d in dists_left] + [d + 1 for d in dists_right]
