from collections import deque, defaultdict
from typing import List

class Solution:
    def minDayskVariants(self, points: List[List[int]], k: int) -> int:
        # Map to store which viruses are at each starting point
        virus_positions = defaultdict(set)
        for idx, (x, y) in enumerate(points):
            virus_positions[(x, y)].add(idx)

        # Queue for BFS: (x, y, day)
        queue = deque()
        visited = set()  # To avoid revisiting the same cell with the same or fewer variants

        # Initialize the queue with all virus starting positions
        for x, y in virus_positions:
            for virus_id in virus_positions[(x, y)]:
                queue.append((x, y, virus_id))
                visited.add(((x, y), frozenset([virus_id])))

        directions = [(-1,0),(1,0),(0,-1),(0,1)]

        while queue:
            x, y, virus_id = queue.popleft()

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                # Get the current set of viruses at this position if it exists
                new_viruses = set()
                found = False
                for state in visited:
                    pos, vs = state
                    if pos == (nx, ny):
                        new_viruses.update(vs)
                        found = True

                if not found:
                    new_viruses = set()

                new_viruses.add(virus_id)

                if len(new_viruses) >= k:
                    return ((abs(nx - points[virus_id][0]) + abs(ny - points[virus_id][1])) + 1) // 2

                state = ((nx, ny), frozenset(new_viruses))
                if state not in visited:
                    visited.add(state)
                    queue.append((nx, ny, virus_id))

        return -1

