from typing import List

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        day_set = set(days)
        last_day = days[-1]
        dp = [0] * (last_day + 1)

        for i in range(1, last_day + 1):
            if i not in day_set:
                dp[i] = dp[i - 1]
            else:
                cost_1day = dp[i - 1] + costs[0]
                cost_7day = dp[max(0, i - 7)] + costs[1]
                cost_30day = dp[max(0, i - 30)] + costs[2]
                dp[i] = min(cost_1day, cost_7day, cost_30day)

        return dp[last_day]

