class Solution:
    def lengthLongestPath(self, input: str) -> int:
        max_len = 0
        path_len = {0: 0}  # depth: current path length up to this depth

        for line in input.split('\n'):
            name = line.lstrip('\t')
            depth = len(line) - len(name)

            if '.' in name:
                # It's a file, update max_len
                max_len = max(max_len, path_len[depth] + len(name))
            else:
                # It's a directory, update the path length for the next depth
                path_len[depth + 1] = path_len[depth] + len(name) + 1  # add 1 for the '/'

        return max_len
