class Solution:
    def lengthLongestPath(self, input: str) -> int:
        longest_path = 0
        depth_map = {0: 0}

        lines = input.split('\n')
        for line in lines:
            stripped_name = line.lstrip('\t')
            current_depth = len(line) - len(stripped_name)

            if '.' in stripped_name:
                # It's a file, calculate path length and update max
                candidate_len = depth_map[current_depth] + len(stripped_name)
                if candidate_len > longest_path:
                    longest_path = candidate_len
            else:
                # It's a directory, update the accumulated length for the next level
                # We add 1 to account for the '/' separator that will precede children
                depth_map[current_depth + 1] = depth_map[current_depth] + len(stripped_name) + 1

        return longest_path

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        from collections import deque, defaultdict

        # Build adjacency list for both colors
        graph = [defaultdict(list) for _ in range(n)]
        for a, b in redEdges:
            graph[a]['red'].append(b)
        for u, v in blueEdges:
            graph[u]['blue'].append(v)

        # Initialize answer array with -1
        answer = [-1] * n
        visited = [[False] * 2 for _ in range(n)]  # visited[node][color], color: 0 for red, 1 for blue

        # BFS queue: (node, next_color, distance)
        # Start at node 0 with no color (can start with either red or blue edge)
        queue = deque()
        queue.append((0, 'red', 0))
        queue.append((0, 'blue', 0))

        while queue:
            node, color, dist = queue.popleft()

            if visited[node][0 if color == 'red' else 1]:
                continue
            visited[node][0 if color == 'red' else 1] = True

            if answer[node] == -1:
                answer[node] = dist

            # Traverse the opposite color edges
            for next_node in graph[node].get('blue' if color == 'red' else 'red', []):
                if not visited[next_node][0 if color == 'blue' else 1]:
                    queue.append((next_node, 'blue' if color == 'red' else 'red', dist + 1))

        return answer

