class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in each submatrix (suffix sum)
        prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                prefix[r][c] = (pizza[r][c] == 'A') + prefix[r+1][c] + prefix[r][c+1] - prefix[r+1][c+1]

        # Check if a submatrix from (r,c) to bottom-right has at least one apple
        def has_apple(r, c):
            return prefix[r][c] - prefix[r][cols] - prefix[rows][c] + prefix[rows][cols] > 0

        @lru_cache(None)
        def dp(r, c, cuts_left):
            if cuts_left == 0:
                return 1 if has_apple(r, c) else 0

            res = 0
            # Try cutting horizontally
            for nr in range(r + 1, rows):
                if has_apple(r, c) and has_apple(nr, c):
                    res = (res + dp(nr, c, cuts_left - 1)) % MOD

            # Try cutting vertically
            for nc in range(c + 1, cols):
                if has_apple(r, c) and has_apple(r, nc):
                    res = (res + dp(r, nc, cuts_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)
