class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute suffix sums (apples in rectangle from (r,c) to bottom-right)
        suffix = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                has_apple = 1 if pizza[r][c] == 'A' else 0
                suffix[r][c] = has_apple + suffix[r+1][c] + suffix[r][c+1] - suffix[r+1][c+1]

        @lru_cache(None)
        def dp(r, c, k_left):
            # If no apples in the current piece, this path is invalid
            if suffix[r][c] == 0:
                return 0

            # Base case: if we need 0 more cuts, the remaining piece must have at least one apple
            if k_left == 0:
                return 1

            res = 0

            # Try horizontal cuts
            for nr in range(r + 1, rows):
                # Check if top part (r to nr-1) has at least one apple
                # Apples in top part = total apples in (r,c) - apples in (nr,c)
                if suffix[r][c] - suffix[nr][c] > 0:
                    res = (res + dp(nr, c, k_left - 1)) % MOD

            # Try vertical cuts
            for nc in range(c + 1, cols):
                # Check if left part (c to nc-1) has at least one apple
                # Apples in left part = total apples in (r,c) - apples in (r,nc)
                if suffix[r][c] - suffix[r][nc] > 0:
                    res = (res + dp(r, nc, k_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

