class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute the number of apples in each submatrix (suffix sum)
        # Renamed 'prefix' to 'apple_count' and used a standard for-loop instead of reversed range
        apple_count = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in range(rows - 1, -1, -1):
            for c in range(cols - 1, -1, -1):
                apple_count[r][c] = (1 if pizza[r][c] == 'A' else 0) + apple_count[r+1][c] + apple_count[r][c+1] - apple_count[r+1][c+1]

        # Helper function renamed to 'contains_apple'
        def contains_apple(r, c):
            return apple_count[r][c] > 0

        @lru_cache(None)
        def dp(r, c, cuts_left):
            if cuts_left == 0:
                return 1 if contains_apple(r, c) else 0

            res = 0

            # Horizontal cuts: check if top part has apple (r,c) and bottom part has apple (nr,c)
            # Logic remains identical, just variable names changed
            for nr in range(r + 1, rows):
                if contains_apple(r, c) and contains_apple(nr, c):
                    res = (res + dp(nr, c, cuts_left - 1)) % MOD

            # Vertical cuts
            for nc in range(c + 1, cols):
                if contains_apple(r, c) and contains_apple(r, nc):
                    res = (res + dp(r, nc, cuts_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

