            for c in reversed(range(cols)):
                prefix[r][c] = (pizza[r][c] == 'A') + prefix[r+1][c] + prefix[r][c+1] - prefix[r+1][c+1]

        # Extract helper logic into a separate method or keep it local but restructure control flow
        # Using while loops instead of for-loops for structural transformation
        def has_apple(r, c):
            return prefix[r][c] - prefix[r][cols] - prefix[rows][c] + prefix[rows][cols] > 0

        @lru_cache(None)
        def dp(r, c, cuts_left):
            if cuts_left == 0:
                return 1 if has_apple(r, c) else 0

            res = 0

            # Horizontal cuts with while loop
            nr = r + 1
            while nr < rows:
                if has_apple(r, c) and has_apple(nr, c):
                    res = (res + dp(nr, c, cuts_left - 1)) % MOD
                nr += 1

            # Vertical cuts with while loop
            nc = c + 1
            while nc < cols:
                if has_apple(r, c) and has_apple(r, nc):
                    res = (res + dp(r, nc, cuts_left - 1)) % MOD
                nc += 1

            return res

        return dp(0, 0, k - 1)

