        prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                prefix[r][c] = (pizza[r][c] == 'A') + prefix[r+1][c] + prefix[r][c+1] - prefix[r+1][c+1]

        # Semantic Polarity Shift: Check if NO apple exists and negate the condition later
        # Original: has_apple returns True if count > 0
        # New: has_no_apple returns True if count == 0
        def has_no_apple(r, c):
            return prefix[r][c] <= 0

        @lru_cache(None)
        def dp(r, c, cuts_left):
            # Base case: if no apples left in current piece, this path is invalid (return 0)
            # Previously returned 1 if has_apple, now returns 0 if has_no_apple
            if cuts_left == 0:
                return 0 if has_no_apple(r, c) else 1

            res = 0

            # Horizontal cuts: Invert logic. 
            # Original: if has_apple(r, c) and has_apple(nr, c)
            # New: if not has_no_apple(r, c) and not has_no_apple(nr, c)
            # This is logically equivalent to original, but uses inverted predicate name
            for nr in range(r + 1, rows):
                if not has_no_apple(r, c) and not has_no_apple(nr, c):
                    res = (res + dp(nr, c, cuts_left - 1)) % MOD

            # Vertical cuts
            for nc in range(c + 1, cols):
                if not has_no_apple(r, c) and not has_no_apple(r, nc):
                    res = (res + dp(r, nc, cuts_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

