class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        from functools import lru_cache

        MOD = 10**9 + 7
        rows, cols = len(pizza), len(pizza[0])

        # Precompute suffix sums
        prefix = [[0] * (cols + 1) for _ in range(rows + 1)]
        for r in reversed(range(rows)):
            for c in reversed(range(cols)):
                prefix[r][c] = (pizza[r][c] == 'A') + prefix[r+1][c] + prefix[r][c+1] - prefix[r+1][c+1]

        def has_apple(r, c):
            return prefix[r][c] > 0

        # Algorithm Variant: Convert recursion to iterative DP with tabulation
        # dp[i][j][k] represents ways to cut pizza from (i,j) into k pieces
        # We use a 3D array instead of memoization

        # Initialize DP table
        # Dimensions: (rows+1) x (cols+1) x (k+1)
        dp_table = [[[0] * (k + 1) for _ in range(cols + 1)] for _ in range(rows + 1)]

        # Base case: 0 cuts left means we need 1 valid piece (if it has apple)
        for i in range(rows):
            for j in range(cols):
                if has_apple(i, j):
                    dp_table[i][j][0] = 1

        # Fill DP table iteratively
        # Order: increasing cuts_left from 1 to k-1
        for cuts_needed in range(1, k):
            for r in range(rows):
                for c in range(cols):
                    if not has_apple(r, c):
                        continue

                    res = 0
                    # Horizontal cuts
                    for nr in range(r + 1, rows):
                        if has_apple(nr, c):
                            res = (res + dp_table[nr][c][cuts_needed - 1]) % MOD

                    # Vertical cuts
                    for nc in range(c + 1, cols):
                        if has_apple(r, nc):
                            res = (res + dp_table[r][nc][cuts_needed - 1]) % MOD

                    dp_table[r][c][cuts_needed] = res

        return dp_table[0][0][k - 1]

