class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        from collections import defaultdict

        # Build the adjacency list and frequency map
        graph = defaultdict(set)
        for u, v in pairs:
            graph[u].add(v)
            graph[v].add(u)

        n = len(graph)
        root = None

        # Find the root node (it must be connected to all other nodes) using while loop
        iterator = iter(graph)
        try:
            while True:
                node = next(iterator)
                if len(graph[node]) == n - 1:
                    root = node
                    break
        except StopIteration:
            pass

        if root is None:
            return 0  # No valid root found

        res = 1
        for node in graph:
            if node == root:
                continue

            curr_neighbors = graph[node]
            parent = None
            min_degree = float('inf')

            # Find a potential parent for this node using recursion-like iteration (simulated by stack logic or just nested loop)
            # Here we convert the inner search to a manual stack approach for structural variation
            candidates = [neighbor for neighbor in curr_neighbors if neighbor != node]

            idx = 0
            while idx < len(candidates):
                neighbor = candidates[idx]
                deg = len(graph[neighbor])
                if deg < min_degree:
                    parent = neighbor
                    min_degree = deg
                idx += 1

            if parent is None or not curr_neighbors.issubset(graph[parent]):
                return 0  # Invalid tree structure

            if len(graph[parent]) == len(curr_neighbors):
                res = 2  # Multiple ways to construct the tree

        return res

