        for i in range(1, len(sorted_nodes)):
            node = sorted_nodes[i]
            curr_neighbors = graph[node]

            # In a sorted-by-degree list, the parent should be among the previously processed nodes
            # We look for the first node in sorted_nodes[0:i] that contains all neighbors of current node
            parent = None
            for j in range(i):
