from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        m = len(pattern)
        n = len(nums)
        result = 0

        # Helper function to determine comparison type
        def get_diff(a, b):
            if a < b:
                return 1
            elif a == b:
                return 0
            else:
                return -1

        # Build comparison array iteratively
        comp = []
        idx = 0
        while idx < n - 1:
            comp.append(get_diff(nums[idx], nums[idx + 1]))
            idx += 1

        # Iterate through possible starting positions
        start = 0
        limit = len(comp) - m + 1
        while start < limit:
            match = True
            k = 0
            while k < m:
                if comp[start + k] != pattern[k]:
                    match = False
                    break
                k += 1
            if match:
                result += 1
            start += 1

        return result

