from typing import List

class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        m = len(pattern)
        n = len(nums)
        result = 0

        # Use a rolling hash approach instead of direct slicing comparison
        # This changes the algorithm from O(m) per window to O(1) per window
        if m == 0:
            return n - 1

        # Compute hash of pattern
        pattern_hash = sum(p * (3 ** k) for k, p in enumerate(pattern))

        # Build comparison array
        comp = []
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                comp.append(1)
            elif nums[i + 1] == nums[i]:
                comp.append(0)
            else:
                comp.append(-1)

        # Compute initial window hash
        current_hash = sum(comp[k] * (3 ** k) for k in range(m))
        if current_hash == pattern_hash:
            result += 1

        # Slide window
        base = 3 ** m
        for i in range(1, len(comp) - m + 1):
            # Remove leading term and add new trailing term
            current_hash = (current_hash - comp[i - 1]) // 3 + comp[i + m - 1] * base
            if current_hash == pattern_hash:
                result += 1

        return result

