class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        len_s = len(s)
        len_p = len(p)
        # Initialize DP table with False values
        dp = [[False] * (len_p + 1) for _ in range(len_s + 1)]
        dp[0][0] = True

        # Process patterns starting with '*'
        j = 1
        while j <= len_p:
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 1]
            else:
                break
            j += 1

        i = 1
        while i <= len_s:
            j = 1
            while j <= len_p:
                char_s = s[i - 1]
                char_p = p[j - 1]

                if char_p == '?' or char_p == char_s:
                    dp[i][j] = dp[i - 1][j - 1]
                elif char_p == '*':
                    dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
                j += 1
            i += 1

        return dp[len_s][len_p]

