class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m = len(s)
        n = len(p)

        def solve(i, j):
            if i == 0 and j == 0:
                return True
            if j == 0:
                return False
            if i == 0:
                # Check if all characters in pattern up to j are '*'
                return all(p[k] == '*' for k in range(j))

            if p[j-1] == '?':
                return solve(i-1, j-1)
            elif p[j-1] == '*':
                # Match zero chars or match one more char
                return solve(i, j-1) or solve(i-1, j)
            else:
                return p[j-1] == s[i-1] and solve(i-1, j-1)

        memo = {}

        def dp_memo(i, j):
            state = (i, j)
            if state in memo:
                return memo[state]

            res = False
            if i == 0 and j == 0:
                res = True
            elif j == 0:
                res = False
            elif i == 0:
                # All previous must be '*'
                k = 0
                while k < j and p[k] == '*':
                    k += 1
                res = (k == j)
            else:
                if p[j-1] == '?':
                    res = dp_memo(i-1, j-1)
                elif p[j-1] == '*':
                    res = dp_memo(i, j-1) or dp_memo(i-1, j)
                else:
                    if p[j-1] == s[i-1]:
                        res = dp_memo(i-1, j-1)
                    else:
                        res = False

            memo[state] = res
            return res

        return dp_memo(m, n)

