        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 1]
            else:
                # Explicitly set non-star to False (redundant but structural change)
                dp[0][j] = False

        for i in range(1, m + 1):
            for j in range(1, n + 1):
