class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)
        # Use two rows instead of full matrix to save space (Space Optimization Variant)
        prev = [False] * (n + 1)
        curr = [False] * (n + 1)

        prev[0] = True

        # Initialize first row (empty string s)
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                prev[j] = prev[j - 1]
            else:
                prev[j] = False

        for i in range(1, m + 1):
            curr[0] = False  # Non-empty string cannot match empty pattern
            for j in range(1, n + 1):
                if p[j - 1] == '?' or p[j - 1] == s[i - 1]:
                    curr[j] = prev[j - 1]
                elif p[j - 1] == '*':
                    curr[j] = curr[j - 1] or prev[j]
                else:
                    curr[j] = False
            # Swap references
            prev, curr = curr, prev

        return prev[n]

