class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        # Greedy approach variant (Two-pointer style)
        # Note: This is a plausible alternative algorithm often used for wildcard matching
        # It uses pointers to track the last seen '*' and matches greedily

        s_idx = 0
        p_idx = 0
        star_idx = -1
        match_idx = 0

        while s_idx < len(s):
            # If current characters match or pattern has '?'
            if p_idx < len(p) and (p[p_idx] == '?' or p[p_idx] == s[s_idx]):
                s_idx += 1
                p_idx += 1
            # If pattern has '*', record position
            elif p_idx < len(p) and p[p_idx] == '*':
                star_idx = p_idx
                match_idx = s_idx
                p_idx += 1
            # If there was a previous '*', backtrack
            elif star_idx != -1:
                p_idx = star_idx + 1
                match_idx += 1
                s_idx = match_idx
            else:
                return False

        # Check if remaining pattern characters are all '*'
        while p_idx < len(p) and p[p_idx] == '*':
            p_idx += 1

        return p_idx == len(p)

