class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m = len(s)
        n = len(p)

        memo = {}

        def dp(i, j):
            state = (i, j)
            if state in memo:
                return memo[state]

            # Base case: both strings exhausted
            if i == 0 and j == 0:
                memo[state] = True
                return True

            # Pattern exhausted but string not
            if j == 0:
                memo[state] = False
                return False

            # String exhausted but pattern remains
            if i == 0:
                # Check if all remaining characters in pattern are '*'
                res = all(p[k] == '*' for k in range(j))
                memo[state] = res
                return res

            # Current pattern character
            pc = p[j-1]

            if pc == '?':
                # Matches any single character
                res = dp(i-1, j-1)
            elif pc == '*':
                # Matches zero characters (dp(i, j-1)) or one/more (dp(i-1, j))
                res = dp(i, j-1) or dp(i-1, j)
            else:
                # Exact match required
                if pc == s[i-1]:
                    res = dp(i-1, j-1)
                else:
                    res = False

            memo[state] = res
            return res

        return dp(m, n)

