class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def removeElements(self, head: Optional[ListNode], val: int) -> Optional[ListNode]:
        # Create a sentinel node to simplify edge cases (e.g., removing head)
        sentinel = ListNode(0)
        sentinel.next = head

        runner = sentinel

        while runner.next is not None:
            if runner.next.val == val:
                runner.next = runner.next.next  # Bypass the matching node
            else:
                runner = runner.next  # Advance only when no removal occurs

        return sentinel.next

