from typing import List

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        start_node = None
        empty_count = 1  # Start with 1 to include the starting square itself in the count of non-obstacle squares

        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    start_node = (r, c)
                elif grid[r][c] == 2:
                    end_node = (r, c)
                if grid[r][c] != -1:
                    empty_count += 1

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        def dfs(r, c, steps, visited):
            if (r, c) == end_node:
                if steps == empty_count:
                    return 1
                return 0

            total_paths = 0
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] != -1 and (nr, nc) not in visited:
                    total_paths += dfs(nr, nc, steps + 1, visited | {(nr, nc)})

            return total_paths

        return dfs(start_node[0], start_node[1], 1, {start_node})

