from typing import List

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        start_pos = None
        end_pos = None
        target_steps = 1

        for r in range(R):
            for c in range(C):
                cell = grid[r][c]
                if cell == 1:
                    start_pos = (r, c)
                elif cell == 2:
                    end_pos = (r, c)
                if cell != -1:
                    target_steps += 1

        # Using a queue for BFS-like expansion but since we need all paths, DFS is better.
        # However, let's use a different control flow: A generator function.
        def generate_paths():
            yield from _dfs(start_pos[0], start_pos[1], 1, {start_pos})

        def _dfs(r, c, steps, visited):
            if (r, c) == end_pos:
                if steps == target_steps:
                    yield 1
                return

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and (nr, nc) not in visited:
                    new_visited = visited | {(nr, nc)}
                    yield from _dfs(nr, nc, steps + 1, new_visited)

        return sum(generate_paths())

