    def partitionString(self, s: str) -> int:
        # Algorithm Variant: Using a bitmask instead of a set since input is lowercase English letters
        count = 0
        mask = 0

        for char in s:
            bit = 1 << (ord(char) - ord('a'))
            if mask & bit:
                count += 1
                mask = bit
            else:
                mask |= bit

        return count + 1

