class Solution:
    def partitionString(self, s: str) -> int:
        def helper(chars, char):
            if char in chars:
                return True, {char}
            chars.add(char)
            return False, chars

        substrings_count = 0
        current_set = set()

        for c in s:
            new_start, updated_set = helper(current_set, c)
            if new_start:
                substrings_count += 1
                current_set = updated_set
            else:
                current_set = updated_set

        return substrings_count + 1

