class Solution:
    def calculate(self, s: str) -> int:
        if not s:
            return 0

        s = s.replace(' ', '')  # Remove all spaces
        stack = []
        num = 0
        sign = '+'

        for i in range(len(s)):
            if s[i].isdigit():
                num = num * 10 + int(s[i])
            if (not s[i].isdigit()) or i == len(s) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    prev = stack.pop()
                    if prev < 0:
                        stack.append(int(-abs(prev) / num))
                    else:
                        stack.append(prev // num)
                sign = s[i]
                num = 0

        return sum(stack)
