class Solution:
    def calculate(self, s: str) -> int:
        if not s:
            return 0

        # Remove spaces by iterating instead of replace
        clean_s = ""
        for c in s:
            if c != ' ':
                clean_s += c

        stack = []
        num = 0
        op = '+'

        for k in range(len(clean_s)):
            char = clean_s[k]
            if char.isdigit():
                num = num * 10 + int(char)

            # Trigger processing at operator or end
            if (not char.isdigit()) or k == len(clean_s) - 1:
                if op == '+':
                    stack.append(num)
                elif op == '-':
                    stack.append(-num)
                elif op == '*':
                    val = stack.pop()
                    stack.append(val * num)
                elif op == '/':
                    val = stack.pop()
                    # Python's // operator truncates toward negative infinity.
                    # We need truncation toward zero.
                    # Using int(val / num) handles both positive and negative correctly for truncation toward zero.
                    stack.append(int(val / num))

                op = char
                num = 0

        result = sum(stack)
        return result

