import math

class Solution:
    def calculate(self, s: str) -> int:
        if not s:
            return 0

        # Remove all whitespace characters
        expression = ''.join(c for c in s if c != ' ')
        operand_stack = []
        current_number = 0
        operator = '+'

        idx = 0
        while idx < len(expression):
            char = expression[idx]
            if char.isdigit():
                current_number = current_number * 10 + int(char)

            # Process when we hit an operator or the end of string
            if (not char.isdigit()) or idx == len(expression) - 1:
                if operator == '+':
                    operand_stack.append(current_number)
                elif operator == '-':
                    operand_stack.append(-current_number)
                elif operator == '*':
                    last_val = operand_stack.pop()
                    operand_stack.append(last_val * current_number)
                elif operator == '/':
                    last_val = operand_stack.pop()
                    # Truncate toward zero manually to ensure correctness across signs
                    if last_val < 0:
                        operand_stack.append(math.ceil(last_val / current_number))
                    else:
                        operand_stack.append(last_val // current_number)

                operator = char
                current_number = 0

            idx += 1

        return sum(operand_stack)

