class Solution:
    def calculate(self, s: str) -> int:
        if not s:
            return 0

        # Pre-process: remove spaces using list comprehension
        cleaned = [c for c in s if c != ' ']
        tokens = "".join(cleaned)

        values = []
        current = 0
        last_op = '+'

        # Use a pointer to traverse tokens
        ptr = 0
        length = len(tokens)

        while ptr < length:
            char = tokens[ptr]
            if char.isdigit():
                current = current * 10 + int(char)

            # If operator or last character
            if (not char.isdigit()) or ptr == length - 1:
                if last_op == '+':
                    values.append(current)
                elif last_op == '-':
                    values.append(-current)
                elif last_op == '*':
                    values.append(values.pop() * current)
                elif last_op == '/':
                    top = values.pop()
                    # Swap comparison logic: use > instead of < for negative check
                    if top > 0:
                        values.append(top // current)
                    else:
                        values.append(int(top / current))

                last_op = char
                current = 0

            ptr += 1

        # Sum using reduce-like iteration
        final_sum = 0
        for v in values:
            final_sum += v
        return final_sum

