            for node in path:
                parent[node] = x
            return x

        def union_sets(a, b):
            root_a = find_set(a)
            root_b = find_set(b)
            if root_a != root_b:
                parent[root_b] = root_a

        i = 1
        while i < n:
            if categoryHandler.haveSameCategory(0, i):
                union_sets(0, i)
            i += 1

        unique_roots = set()
        for j in range(n):
            unique_roots.add(find_set(j))

        return len(unique_roots)

