    def numberOfCategories(self, n: int, categoryHandler: 'CategoryHandler') -> int:
        if n <= 0:
            return 0

        parent = list(range(n))

        def find_representative(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def link_groups(a, b):
            rep_a = find_representative(a)
            rep_b = find_representative(b)
