class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        if n == 0:
            return 0

        # Use a list to store the representative index of each unique category found so far.
        # The first element (0) is always the representative of the first category.
        representatives = [0]

        for i in range(1, n):
            is_new_category = True
            # Check if current element 'i' belongs to any existing category represented by 'rep'
            for rep in representatives:
                if categoryHandler.haveSameCategory(i, rep):
                    is_new_category = False
                    break

            # If it doesn't match any existing category, add it as a new representative
            if is_new_category:
                representatives.append(i)

        return len(representatives)

