class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        def process_segment(segment):
            if not segment:
                return ""
            inner = segment[1:-1]
            return inner

        parts = []
        balance = 0
        start = 0

        for i, ch in enumerate(s):
            if ch == '(':
                balance += 1
            else:
                balance -= 1

            if balance == 0:
                primitive = s[start:i+1]
                parts.append(process_segment(primitive))
                start = i + 1

        return "".join(parts)

