class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        stack = []
        current_primitive = []
        result = []

        for char in s:
            if char == '(':
                stack.append(char)
                if len(stack) > 1:
                    current_primitive.append(char)
            else:
                if len(stack) > 1:
                    current_primitive.append(char)
                stack.pop()
                if not stack:
                    result.append("".join(current_primitive))
                    current_primitive = []

