from typing import List

class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        def count_parity(nums, target_parity):
            c = 0
            i = 0
            while i < len(nums):
                if nums[i] % 2 == target_parity:
                    c += 1
                i += 1
            return c

        evens = count_parity(position, 0)
        odds = count_parity(position, 1)

        return evens if evens < odds else odds

