class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        # Count chips at even positions and odd positions
        cnt_even = 0
        cnt_odd = 0

        # Iterate through positions to tally parities
        for p in position:
            if p & 1 == 0:
                cnt_even += 1
            else:
