from typing import List

class Solution:
    def smallestRangeI(self, nums: List[int], k: int) -> int:
        min_val = min(nums)
        max_val = max(nums)

        low_bound = min_val + k
        high_bound = max_val - k

        return max(0, high_bound - low_bound)

