class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        # Build a parent map to store the parent of each region
        parent = {}

        for region_list in regions:
            parent_of = region_list[0]
            for child in region_list[1:]:
                parent[child] = parent_of

        # Get the path from region1 to the root (including region1 and all ancestors)
        path = set()
        curr = region1
        while curr is not None:
            path.add(curr)
            curr = parent.get(curr)  # Use .get to safely handle missing keys (though guaranteed to exist per problem)

        # Now traverse from region2 upwards until we find a node in the path
        curr = region2
        while curr not in path:
            curr = parent[curr]

        return curr

