class Solution:
    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        # Initialize a 2D DP array where dp[i][j] represents the maximum number of strings
        # that can be included with at most i 0's and j 1's.
        table = [[0] * (n + 1) for _ in range(m + 1)]

        for s in strs:
            count_0 = s.count('0')
            count_1 = s.count('1')

            # Traverse from m down to count_0 and n down to count_1 to avoid using the same string multiple times
            for x in range(m, count_0 - 1, -1):
                for y in range(n, count_1 - 1, -1):
                    table[x][y] = max(table[x][y], table[x - count_0][y - count_1] + 1)

