class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(parents)
        adj = [[] for _ in range(n)]

        # Build the tree
        for i in range(1, n):
            adj[parents[i]].append(i)

        output = [1] * n

        # Find the node with value 1
        start_node = -1
        for i in range(n):
            if nums[i] == 1:
                start_node = i
                break

        if start_node != -1:
            seen = set()
            miss = 1

            # Traverse up from the node containing 1 to the root
            curr = start_node
            while curr != -1:
                # Collect all values in the subtree of 'curr' that haven't been processed yet
                stack = [curr]
                while stack:
                    u = stack.pop()
                    if nums[u] not in seen:
                        seen.add(nums[u])
                        for v in adj[u]:
                            stack.append(v)

                # Update miss
                while miss in seen:
                    miss += 1

                output[curr] = miss
                curr = parents[curr]

        return output

