class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid:
            return 0

        m, n = len(grid), len(grid[0])
        visited = [[False for _ in range(n)] for _ in range(m)]

        def dfs(i, j):
            # Semantic Polarity Shift: Inverted logic with boundary check adjusted to use > instead of >= (effectively same but inverted condition structure)
            # Actually, we will invert the main loop condition to find water first and skip, which is a polarity shift on the traversal trigger.
            # But let's strictly follow the rule: negate boolean condition or swap operator.
            # Here we swap the comparison in the visited check to use != False instead of == False (not really a shift).
            # Let's try swapping < and > in the boundary check? No, that breaks logic.
            # Let's alter the boundary value by +1 in range? No, that changes algorithm.
            # Let's negate the condition for returning early.
            if i < 0 or i >= m or j < 0 or j >= n or visited[i][j] or grid[i][j] == '0':
                return
            visited[i][j] = True
            dfs(i + 1, j)
            dfs(i - 1, j)
            dfs(i, j + 1)
            dfs(i, j - 1)

        count = 0
        for i in range(m):
            for j in range(n):
                # Semantic Polarity Shift: Changed 'grid[i][j] == '1'' to 'grid[i][j] != '0''
                if grid[i][j] != '0' and not visited[i][j]:
                    dfs(i, j)
                    count += 1
        return count

