from typing import List

class Solution:
    def findPermutation(self, s: str) -> List[int]:
        n = len(s) + 1
        result = list(range(1, n))
        i = 0

        while i < n - 1:
            if s[i] == 'D':
                j = i
                # Locate the end of the consecutive 'D' segment
                while j + 1 < n and s[j] == 'D':
                    j += 1
                # Reverse the identified slice to satisfy the condition
                result[i : j + 1] = reversed(result[i : j + 1])
                i = j + 1
            else:
                i += 1

        return result

