from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])

        # If k is large enough to clear the shortest path (Manhattan distance), return it directly
        if k >= m + n - 2:
            return m + n - 2

        # BFS queue: (row, col, remaining_k, steps)
        queue = deque([(0, 0, k, 0)])
        # Visited set: stores (row, col, remaining_k)
        visited = {(0, 0, k)}

        while queue:
            r, c, rem_k, steps = queue.popleft()

            # Check if we reached the destination
            if r == m - 1 and c == n - 1:
                return steps

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc

                if 0 <= nr < m and 0 <= nc < n:
                    cost = 1 if grid[nr][nc] == 1 else 0
                    new_rem = rem_k - cost

                    if new_rem >= 0 and (nr, nc, new_rem) not in visited:
                        visited.add((nr, nc, new_rem))
                        queue.append((nr, nc, new_rem, steps + 1))

        return -1

