        q.append((0, 0, k))
        seen.add((0, 0, k))

        dist = 0

        moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            level_size = len(q)
            for _ in range(level_size):
                r, c, rem_k = q.popleft()

                if r == rows - 1 and c == cols - 1:
                    return dist

                for dr, dc in moves:
                    nr, nc = r + dr, c + dc

                    if 0 <= nr < rows and 0 <= nc < cols:
                        cost = 1 if grid[nr][nc] == 1 else 0
                        next_k = rem_k - cost

                        if next_k >= 0 and (nr, nc, next_k) not in seen:
                            seen.add((nr, nc, next_k))
                            q.append((nr, nc, next_k))

            dist += 1

