from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])

        if grid[0][0] == 1 and k == 0:
            return -1

        queue = deque([(0, 0, k)])
        visited_set = {(0, 0, k)}

        current_step = 0

        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            size = len(queue)
            idx = 0
            while idx < size:
                row, col, elim_count = queue.popleft()

                if row == m - 1 and col == n - 1:
                    return current_step

                for d_row, d_col in dirs:
                    new_row = row + d_row
                    new_col = col + d_col

                    if 0 <= new_row < m and 0 <= new_col < n:
                        remaining = elim_count
                        if grid[new_row][new_col] == 1:
                            remaining -= 1

                        state = (new_row, new_col, remaining)
                        if remaining >= 0 and state not in visited_set:
                            visited_set.add(state)
                            queue.append(state)
                idx += 1

            current_step += 1

        return -1

