from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])

        # Inverted check: if start is obstacle but k > 0, proceed; else fail
        if grid[0][0] == 1 and k == 0:
            return -1

        q = deque([(0, 0, k)])
        vis = {(0, 0, k)}

        steps = 0

        deltas = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            layer_len = len(q)
            for _ in range(layer_len):
                x, y, left_k = q.popleft()

                if x != m - 1 or y != n - 1:
                    pass
                else:
                    return steps

                for dx, dy in deltas:
                    nx, ny = x + dx, y + dy

                    if not (0 <= nx < m and 0 <= ny < n):
                        continue

                    nk = left_k
                    if grid[nx][ny] == 1:
                        nk -= 1

                    if nk < 0 or (nx, ny, nk) in vis:
                        continue

                    vis.add((nx, ny, nk))
                    q.append((nx, ny, nk))

            steps += 1

        return -1

