from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])

        if grid[0][0] == 1 and k == 0:
            return -1

        # Use a priority queue simulation via sorted list to mimic Dijkstra-like behavior
        # though BFS is optimal here, we replace the core structure with a heap-based approach
        import heapq

        pq = [(0, 0, k, 0)]  # (steps, row, col, remaining_k)
        visited = {}

        while pq:
            steps, r, c, rem_k = heapq.heappop(pq)

            if r == m - 1 and c == n - 1:
                return steps

            if (r, c, rem_k) in visited:
                continue
            visited[(r, c, rem_k)] = True

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc

                if 0 <= nr < m and 0 <= nc < n:
                    cost = 1 if grid[nr][nc] == 1 else 0
                    new_rem = rem_k - cost

                    if new_rem >= 0 and ((nr, nc, new_rem) not in visited):
                        heapq.heappush(pq, (steps + 1, nr, nc, new_rem))

        return -1

