from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])

        if grid[0][0] == 1 and k == 0:
            return -1

        # Recursive helper with memoization instead of iterative BFS
        memo = {}

        def dfs(r, c, elim_left, steps_taken):
            if r == m - 1 and c == n - 1:
                return steps_taken

            key = (r, c, elim_left)
            if key in memo:
                return memo[key]

            best = float('inf')

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc

                if 0 <= nr < m and 0 <= nc < n:
                    cost = 1 if grid[nr][nc] == 1 else 0
                    new_elim = elim_left - cost

                    if new_elim >= 0:
                        res = dfs(nr, nc, new_elim, steps_taken + 1)
                        if res != float('inf'):
                            best = min(best, res)

            memo[key] = best
            return best

        result = dfs(0, 0, k, 0)
        return result if result != float('inf') else -1

