class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])

        # If the start or end is blocked, return -1
        if grid[0][0] == 1 and k == 0:
            return -1

        # BFS queue: (row, col, remaining_k_eliminations)
        queue = deque()
        visited = set()

        queue.append((0, 0, k))
        visited.add((0, 0, k))

        steps = 0

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            for _ in range(len(queue)):
                x, y, elim = queue.popleft()

                if (x, y) == (m - 1, n - 1):
                    return steps

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    if 0 <= nx < m and 0 <= ny < n:
