from collections import deque
from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])

        if m == 1 and n == 1:
            return 0

        queue = deque([(0, 0, k, 0)])
        visited_set = {(0, 0, k)}

        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            row, col, elim_count, steps = queue.popleft()

            for d_row, d_col in dirs:
                new_row = row + d_row
                new_col = col + d_col

                if 0 <= new_row < m and 0 <= new_col < n:
                    remaining = elim_count
                    if grid[new_row][new_col] == 1:
                        remaining -= 1

                    if remaining >= 0:
                        if new_row == m - 1 and new_col == n - 1:
                            return steps + 1

                        state = (new_row, new_col, remaining)
                        if state not in visited_set:
                            visited_set.add(state)
                            queue.append((new_row, new_col, remaining, steps + 1))

        return -1

