from typing import List

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])

        # Optimization: If we can eliminate more obstacles than the shortest possible path length (Manhattan distance - 1),
        # we can just take the direct path. The minimum steps is m + n - 2.
        if k >= m + n - 2:
            return m + n - 2

        q = deque([(0, 0, k)])
        vis = {(0, 0, k)}

        steps = 0

        deltas = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            layer_len = len(q)
            for _ in range(layer_len):
                x, y, left_k = q.popleft()

                if x == m - 1 and y == n - 1:
                    return steps

                for dx, dy in deltas:
                    nx, ny = x + dx, y + dy

                    if not (0 <= nx < m and 0 <= ny < n):
                        continue

                    nk = left_k
                    if grid[nx][ny] == 1:
                        nk -= 1

                    if nk < 0 or (nx, ny, nk) in vis:
                        continue

                    vis.add((nx, ny, nk))
                    q.append((nx, ny, nk))

            steps += 1

        return -1

