class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        from collections import deque

        rows, cols = len(grid), len(grid[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Find initial positions
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 'C':
                    cat = (i, j)
                elif grid[i][j] == 'M':
                    mouse = (i, j)
                elif grid[i][j] == 'F':
                    food = (i, j)

        max_turns = 1000

        # memo[(mouse_pos, cat_pos, turn)] = result (True if Mouse wins, False otherwise)
        memo = {}

        def get_moves(pos, jump, is_cat):
            r, c = pos
            moves = []
            for dr, dc in directions:
                dist = 0
                nr, nc = r, c
                while True:
                    nr += dr
                    nc += dc
                    dist += 1
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                        break
                    moves.append((nr, nc))
                    if dist >= (catJump if is_cat else mouseJump):
                        break
            moves.append(pos)  # staying in place is allowed
            return list(set(moves))  # remove duplicates

        def dp(mouse_pos, cat_pos, turn):
            if turn >= max_turns:
                return False  # Cat wins by time limit
            if mouse_pos == food:
                return True  # Mouse wins
            if cat_pos == food:
                return False  # Cat wins
            if mouse_pos == cat_pos:
                return False  # Cat wins

            key = (mouse_pos, cat_pos, turn)
            if key in memo:
                return memo[key]

            is_mouse_turn = (turn % 2 == 0)
            if is_mouse_turn:
                moves = get_moves(mouse_pos, mouseJump, False)
                for next_mouse in moves:
                    if dp(next_mouse, cat_pos, turn + 1):
                        memo[key] = True
                        return True
                memo[key] = False
                return False
            else:
                moves = get_moves(cat_pos, catJump, True)
                for next_cat in moves:
                    if not dp(mouse_pos, next_cat, turn + 1):
                        memo[key] = False
                        return False
                memo[key] = True
                return True

        return dp(mouse, cat, 0)
