class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        from collections import deque

        rows, cols = len(grid), len(grid[0])
        moves_dir = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        c0, m0, f0 = None, None, None
        for i in range(rows):
            for j in range(cols):
                cell = grid[i][j]
                if cell == 'C':
                    c0 = (i, j)
                elif cell == 'M':
                    m0 = (i, j)
                elif cell == 'F':
                    f0 = (i, j)

        # Total states: rows*cols * rows*cols * 2 turns * 1000? 
        # Actually we use a state space of (mouse_pos, cat_pos, turn)
        # Since max turns is 1000, but the game must end within 1000.
        # However, the state space is actually small enough because positions are limited (8x8=64).
        # Max states = 64 * 64 * 2 = 8192 per turn? No, we need to track depth.
        # But standard solution uses minimax with memoization or BFS on state graph.
        # The constraint is 1000 turns. We can model this as a game on a graph.
        # Let's use a topological sort / BFS approach (coloring) or memoized DFS.
        # Given the constraints and the "optimal play", we need to determine winning/losing/draw.
        # But here, draw is impossible (max 1000 turns -> Cat wins). So it's Win/Loss.

        # State: (mouse_pos, cat_pos, turn)
        # Turn 0: Mouse move, Turn 1: Cat move, ...
        # If turn >= 1000, Cat wins (return False for Mouse).

        # We will use memoization.
        # To avoid infinite recursion, we rely on the turn cap.

        dp_map = {}

        def get_reachable(p, jump, is_cat):
            r, c = p
            seen = set()
            seen.add(p)
            for dr, dc in moves_dir:
                nr, nc = r, c
                for dist in range(1, jump + 1):
                    nr += dr
                    nc += dc
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                        break
                    seen.add((nr, nc))
            return list(seen)

        def solve(mouse_p, cat_p, t):
            if t >= 1000:
                return False # Cat wins

            if mouse_p == f0:
                return True # Mouse wins
            if cat_p == f0:
                return False # Cat wins
            if mouse_p == cat_p:
                return False # Cat wins

            state = (mouse_p, cat_p, t)
            if state in dp_map:
                return dp_map[state]

            if t % 2 == 0:
                # Mouse's turn
                possible_moves = get_reachable(mouse_p, mouseJump, False)
                can_win = False
                for nm in possible_moves:
                    if solve(nm, cat_p, t + 1):
                        can_win = True
                        break
                dp_map[state] = can_win
                return can_win
            else:
                # Cat's turn
                possible_moves = get_reachable(cat_p, catJump, True)
                # Cat wants to prevent Mouse from winning.
                # Mouse wins only if ALL paths lead to Mouse win? No.
                # Cat plays optimally to make Mouse lose.
                # If there exists ANY move for Cat such that Mouse loses (returns False), then Cat wins (return False).
                # If for ALL moves Cat makes, Mouse wins (returns True), then Mouse wins (return True).

                cat_can_force_loss = False
                for nc in possible_moves:
                    if not solve(mouse_p, nc, t + 1):
                        cat_can_force_loss = True
                        break

                dp_map[state] = not cat_can_force_loss
                return not cat_can_force_loss

        return solve(m0, c0, 0)

