class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        from collections import deque

        rows, cols = len(grid), len(grid[0])
        deltas = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        c_init, m_init, f_loc = None, None, None
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                if val == 'C':
                    c_init = (r, c)
                elif val == 'M':
                    m_init = (r, c)
                elif val == 'F':
                    f_loc = (r, c)

        TURN_LIMIT = 1000
        cache = {}

        def get_all_destinations(current, jump_max, is_cat_move):
            cr, cc = current
            options = {current}
            for dr, dc in deltas:
                step = 0
                nr, nc = cr, cc
                while True:
                    nr += dr
                    nc += dc
                    step += 1
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                        break
                    options.add((nr, nc))
                    if step >= (catJump if is_cat_move else mouseJump):
                        break
            return list(options)

        def simulate(mouse_pt, cat_pt, t):
            if t >= TURN_LIMIT:
                return False
            if mouse_pt == f_loc:
                return True
            if cat_pt == f_loc:
                return False
            if mouse_pt == cat_pt:
                return False

            state = (mouse_pt, cat_pt, t)
            if state in cache:
                return cache[state]

            if t % 2 == 0:
                cand = get_all_destinations(mouse_pt, mouseJump, False)
                for nm in cand:
                    if simulate(nm, cat_pt, t + 1):
                        cache[state] = True
                        return True
                cache[state] = False
                return False
            else:
                cand = get_all_destinations(cat_pt, catJump, True)
                for nc in cand:
                    if not simulate(mouse_pt, nc, t + 1):
                        cache[state] = False
                        return False
                cache[state] = True
                return True

        return simulate(m_init, c_init, 0)

