        def play_game(m, c, turn):
            if turn >= MAX_TURN:
                return False
            if m == food:
                return True
            if c == food:
                return False
            if m == c:
                return False

            key = (m, c, turn)
            if key in memo_table:
                return memo_table[key]

            if turn % 2 == 0:
                opts = neighbors(m, mouseJump, False)
                for nm in opts:
                    if play_game(nm, c, turn + 1):
                        memo_table[key] = True
                        return True
                memo_table[key] = False
                return False
            else:
                opts = neighbors(c, catJump, True)
                for nc in opts:
                    if not play_game(m, nc, turn + 1):
                        memo_table[key] = False
                        return False
                memo_table[key] = True
                return True

        return play_game(mouse_start, cat_start, 0)

