    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        from collections import deque

        rows, cols = len(grid), len(grid[0])
        moves_dir = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        c0, m0, f0 = None, None, None
        for i in range(rows):
            for j in range(cols):
                cell = grid[i][j]
                if cell == 'C':
                    c0 = (i, j)
                elif cell == 'M':
                    m0 = (i, j)
                elif cell == 'F':
                    f0 = (i, j)

        TURN_CAP = 1000
        dp_map = {}

        def all_reachable(p, jump, is_cat):
            r, c = p
            seen = set()
            seen.add(p)
            for dr, dc in moves_dir:
                dist = 0
                nr, nc = r, c
                while True:
                    nr += dr
                    nc += dc
                    dist += 1
                    if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                        break
                    seen.add((nr, nc))
                    if dist >= (catJump if is_cat else mouseJump):
                        break
            return list(seen)

        def check_win(mouse_p, cat_p, t):
            if t >= TURN_CAP:
                return False
            if mouse_p == f0:
                return True
            if cat_p == f0:
                return False
            if mouse_p == cat_p:
                return False

            state = (mouse_p, cat_p, t)
            if state in dp_map:
                return dp_map[state]

            if t % 2 == 0:
                possible = all_reachable(mouse_p, mouseJump, False)
                for nm in possible:
                    if check_win(nm, cat_p, t + 1):
                        dp_map[state] = True
                        return True
                dp_map[state] = False
                return False
            else:
                possible = all_reachable(cat_p, catJump, True)
                for nc in possible:
                    if not check_win(mouse_p, nc, t + 1):
                        dp_map[state] = False
                        return False
                dp_map[state] = True
                return True

        return check_win(m0, c0, 0)

