class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        from collections import OrderedDict

        if valueDiff < 0 or indexDiff <= 0:
            return False

        bucket_size = valueDiff + 1  # Size of each bucket to group numbers
        buckets = {}

        for i in range(len(nums)):
            num = nums[i]
            bucket_id = num // bucket_size

            # Check the current bucket
            if bucket_id in buckets:
                return True

            # Check the previous bucket
            if (bucket_id - 1) in buckets and abs(num - buckets[bucket_id - 1]) <= valueDiff:
                return True

            # Check the next bucket
            if (bucket_id + 1) in buckets and abs(num - buckets[bucket_id + 1]) <= valueDiff:
                return True

            # Add current number to the bucket
            buckets[bucket_id] = num

            # Remove the element that is out of the index window
            if i >= indexDiff:
                remove_bucket_id = nums[i - indexDiff] // bucket_size
                del buckets[remove_bucket_id]

        return False
