class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        from sortedcontainers import SortedList

        if valueDiff < 0 or indexDiff <= 0:
            return False

        window = SortedList()

        for i in range(len(nums)):
            num = nums[i]

            # Check if there exists a number in the window within valueDiff
            # We look for a number x such that num - valueDiff <= x <= num + valueDiff
            left_idx = window.bisect_left(num - valueDiff)
            right_idx = window.bisect_right(num + valueDiff)

            if left_idx < right_idx:
                return True

            # Add current number to the window
            window.add(num)

            # Remove the element that is out of the index window
            if i >= indexDiff:
                window.remove(nums[i - indexDiff])

        return False

