class Solution:
    def numSubmat(self, mat: List[List[int]]) -> int:
        m, n = len(mat), len(mat[0])

        # Precompute the number of consecutive 1s ending at each cell in the same row
        for i in range(m):
            for j in range(1, n):
                if mat[i][j] == 1:
                    mat[i][j] += mat[i][j - 1]

        result = 0

        # For each cell, calculate all submatrices that can be formed with it as bottom-right corner
        for i in range(m):
            for j in range(n):
                if mat[i][j] > 0:
                    min_width = mat[i][j]
                    k = i
                    while k >= 0 and mat[k][j] > 0:
                        min_width = min(min_width, mat[k][j])
                        result += min_width
                        k -= 1

        return result
