class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        if not nums:
            return []

        # Structural Transformation: Extract verification into a helper function
        def verify_candidates(candidates, data, limit):
            verified = []
            for cand in candidates:
                if cand is None:
                    continue
                c = 0
                for x in data:
                    if x == cand:
                        c += 1
                if c > limit:
                    verified.append(cand)
            return verified

        # Step 1: Find potential candidates using Boyer-Moore Voting Algorithm
        candidate1, candidate2 = None, None
        count1, count2 = 0, 0

        for num in nums:
            if num == candidate1:
                count1 += 1
            elif num == candidate2:
                count2 += 1
            elif count1 == 0:
                candidate1 = num
                count1 = 1
            elif count2 == 0:
                candidate2 = num
                count2 = 1
            else:
                count1 -= 1
                count2 -= 1

        # Step 2: Verify the candidates using helper
        threshold = len(nums) // 3
        candidates_list = [candidate1, candidate2]

        raw_result = verify_candidates(candidates_list, nums, threshold)

        # Ensure uniqueness in result list (though logic handles it mostly)
        final_result = []
        seen = set()
        for item in raw_result:
            if item not in seen:
                seen.add(item)
                final_result.append(item)

        return final_result

