class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        from collections import defaultdict, deque

        n = len(words)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px = find(x)
            py = find(y)
            if px != py:
                parent[px] = py

        # Convert each word to a bitmask for efficient comparison
        masks = []
        for word in words:
            mask = 0
            for ch in word:
                mask |= 1 << (ord(ch) - ord('a'))
            masks.append(mask)

        for i in range(n):
            mask_i = masks[i]
            for j in range(i + 1, n):
                mask_j = masks[j]
                if bin(mask_i ^ mask_j).count('1') == 1:
                    # Case 1: Replace one letter
                    union(i, j)
                elif bin(mask_i & mask_j).bit_count() == mask_i.bit_count() - 1:
                    # Case 2: Delete one letter from s1 to get s2
                    union(i, j)
                elif bin(mask_j & mask_i).bit_count() == mask_j.bit_count() - 1:
                    # Case 3: Delete one letter from s2 to get s1
                    union(i, j)

        group_count = defaultdict(int)
        for i in range(n):
            root = find(i)
            group_count[root] += 1

        max_groups = len(group_count)
        largest_group = max(group_count.values())

        return [max_groups, largest_group]
