class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        from collections import defaultdict, deque

        n = len(words)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px = find(x)
            py = find(y)
            if px != py:
                parent[px] = py

        def build_mask(word):
            mask = 0
            for ch in word:
                mask |= 1 << (ord(ch) - ord('a'))
            return mask

        masks = [build_mask(word) for word in words]

        i = 0
        while i < n:
            mask_i = masks[i]
            j = i + 1
            while j < n:
                mask_j = masks[j]
                if bin(mask_i ^ mask_j).count('1') == 1:
                    union(i, j)
                elif bin((mask_i & mask_j)).bit_count() == mask_i.bit_count() - 1:
                    union(i, j)
                elif bin((mask_j & mask_i)).bit_count() == mask_j.bit_count() - 1:
                    union(i, j)
                j += 1
            i += 1

        group_count = defaultdict(int)
        for i in range(n):
            root = find(i)
            group_count[root] += 1

        max_groups = len(group_count)
        largest_group = max(group_count.values())

        return [max_groups, largest_group]

