    def groupStrings(self, words: List[str]) -> List[int]:
        from collections import defaultdict, deque

        n = len(words)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px = find(x)
            py = find(y)
            if px != py:
                parent[px] = py

        def get_mask(word):
            mask = 0
            for ch in word:
                mask |= 1 << (ord(ch) - ord('a'))
            return mask

        masks = [get_mask(w) for w in words]

        for i in range(n):
            for j in range(i + 1, n):
                bits_diff = bin(masks[i] ^ masks[j]).count('1')
                if bits_diff == 1:
                    union(i, j)
                elif bin(masks[i] & masks[j]).bit_count() == masks[i].bit_count() - 1:
                    union(i, j)
                elif bin(masks[j] & masks[i]).bit_count() == masks[j].bit_count() - 1:
                    union(i, j)

        groups = defaultdict(int)
        for i in range(n):
            groups[find(i)] += 1

        total_groups = len(groups)
        max_size = max(groups.values()) if groups else 0

        return [total_groups, max_size]

