    def groupStrings(self, words: List[str]) -> List[int]:
        from collections import defaultdict, deque

        n = len(words)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px = find(x)
            py = find(y)
            if px != py:
                parent[px] = py

        masks = []
        for word in words:
            mask = 0
            for c in word:
                mask |= 1 << (ord(c) - ord('a'))
            masks.append(mask)

        # Check all pairs to determine connections
        for i in range(n):
            for j in range(i + 1, n):
                diff = bin(masks[i] ^ masks[j]).count('1')
                if diff == 1:
                    union(i, j)
                elif bin(masks[i] & masks[j]).bit_count() == masks[i].bit_count() - 1:
                    union(i, j)
                elif bin(masks[j] & masks[i]).bit_count() == masks[j].bit_count() - 1:
                    union(i, j)

        group_map = defaultdict(list)
        for i in range(n):
            group_map[find(i)].append(i)

