from typing import List

class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        # Sort tasks by their end time to process earlier deadlines first
        tasks.sort(key=lambda x: x[1])

        on_time = set()

        for start, end, duration in tasks:
            # Count how many seconds in the current task's range are already covered
            covered = 0
            for t in range(start, end + 1):
                if t in on_time:
                    covered += 1

            remaining = duration - covered

            # Fill in the missing required durations, prioritizing times that might help future tasks.
            # Since we sorted by end time, filling from right to left (end down to start) is a greedy strategy 
            # that helps cover tasks ending later or overlapping at the end of the current interval.
            t = end
            while remaining > 0 and t >= start:
                if t not in on_time:
                    on_time.add(t)
                    remaining -= 1
                t -= 1

        return len(on_time)

