class Solution:
    def recoverArray(self, n: int, sums: List[int]) -> List[int]:
        from collections import Counter

        sums.sort()
        result = []
        total = 0

        for _ in range(n):
            # Try the smallest non-zero sum as a candidate element
            for i in range(1, len(sums)):
                if sums[i] != 0:
                    x = sums[i]
                    break
            else:
                x = 0  # All are zero, so we just pick 0

            count = Counter()
            new_sums = []

            for s in sums:
                if count[s - x] > 0:
                    count[s - x] -= 1
                    new_sums.append(s)
                elif count[s] > 0:
                    count[s] -= 1
                    new_sums.append(s)
                else:
                    count[s] += 1

            if len(new_sums) == len(sums) // 2:
                result.append(x)
                sums = new_sums
                break

        return result
