class Solution:
    def maximizeWin(self, prizePositions: List[int], k: int) -> int:
        n = len(prizePositions)
        max_first = [0] * n
        max_second = [0] * n

        # Precompute the maximum number of prizes we can collect with one segment ending at or before i
        j = 0
        for i in range(n):
            while j < n and prizePositions[j] - prizePositions[i] <= k:
                j += 1
            max_first[i] = j - i

        # Precompute the maximum number of prizes we can collect with one segment starting at or after i
        j = n - 1
        for i in range(n - 1, -1, -1):
            while j >= 0 and prizePositions[j] - prizePositions[i] > k:
                j -= 1
            max_second[i] = i - j + 1

        # Now find the best pair of segments (non-overlapping or overlapping is allowed)
        res = 0
        left = 0
        for right in range(n):
            while prizePositions[right] - prizePositions[left] > k:
                left += 1
            current = right - left + 1
            if left > 0:
                current += max_second[left]
            if right < n - 1:
                current = max(current, max_first[right] + (n - right - 1))
            res = max(res, current)

        return res
