class Solution:
    def maximizeWin(self, prizePositions: List[int], k: int) -> int:
        n = len(prizePositions)
        if n == 0:
            return 0

        # Helper to compute max prizes in a single window ending at or before index i
        def compute_max_first():
            arr = [0] * n
            j = 0
            for i in range(n):
                while j < n and prizePositions[j] - prizePositions[i] <= k:
                    j += 1
                arr[i] = j - i
            return arr

        # Helper to compute max prizes in a single window starting at or after index i
        def compute_max_second():
            arr = [0] * n
            j = n - 1
            for i in range(n - 1, -1, -1):
                while j >= 0 and prizePositions[j] - prizePositions[i] > k:
                    j -= 1
                arr[i] = i - j + 1
            return arr

        max_first = compute_max_first()
        max_second = compute_max_second()

        # Now find the best pair of segments (non-overlapping or overlapping is allowed)
        res = 0
        left = 0
        for right in range(n):
            while prizePositions[right] - prizePositions[left] > k:
                left += 1
            current = right - left + 1
            if left > 0:
                current += max_second[left]
            if right < n - 1:
                current = max(current, max_first[right] + (n - right - 1))
            res = max(res, current)

        return res

