from typing import List

class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:
        corner_points = set()
        current_area = 0
        minX = minY = float('inf')
        maxX = maxY = float('-inf')

        for x1, y1, x2, y2 in rectangles:
            current_area += (x2 - x1) * (y2 - y1)

            if x1 < minX: minX = x1
            if y1 < minY: minY = y1
            if x2 > maxX: maxX = x2
            if y2 > maxY: maxY = y2

            candidates = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
            for p in candidates:
                if p in corner_points:
                    corner_points.remove(p)
                else:
                    corner_points.add(p)

        expected_area = (maxX - minX) * (maxY - minY)

        if current_area != expected_area or len(corner_points) != 4:
            return False

        required = {(minX, minY), (minX, maxY), (maxX, minY), (maxX, maxY)}

        return required == corner_points

