from typing import List

class Solution:
    def wiggleSort(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        # Semantic Polarity Shift: Inverted logic using 'not' and swapped operators
        # Original: (odd and <) or (even and >)
        # New: (odd and >=) is false => swap needed if odd and not >= (i.e. <)
        # Let's invert the condition check directly to trigger swap on failure of desired order
        for i in range(1, len(nums)):
            is_odd = (i % 2 == 1)
            # Desired: odd index should be >= prev, even index should be <= prev
            # If NOT (is_odd and nums[i] >= nums[i-1]) AND NOT (not is_odd and nums[i] <= nums[i-1])
            # Simplified to match original logic via De Morgan's:
