import bisect

class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)

        # Compute LIS using O(N log N) approach with binary search
        def get_lis_lengths(arr):
            tails = []
            lengths = [0] * len(arr)
            for i, x in enumerate(arr):
                pos = bisect.bisect_left(tails, x)
                if pos == len(tails):
                    tails.append(x)
                else:
                    tails[pos] = x
                lengths[i] = pos + 1
            return lengths

        lis_left = get_lis_lengths(nums)

        # For the right side, we reverse the array and find LIS of reversed array
        # which corresponds to longest decreasing subsequence from original perspective
        lis_right_rev = get_lis_lengths(nums[::-1])
        lis_right = lis_right_rev[::-1]

        max_mountain = 0
        for i in range(1, n - 1):
            if lis_left[i] >= 2 and lis_right[i] >= 2:
                max_mountain = max(max_mountain, lis_left[i] + lis_right[i] - 1)

        return n - max_mountain

