    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)

        # Compute LIS from left (Longest Increasing Subsequence ending at i)
        lis_left = [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i]:
                    lis_left[i] = max(lis_left[i], lis_left[j] + 1)

        # Compute LDS from right (Longest Decreasing Subsequence starting at i going right)
        # This is equivalent to finding the longest increasing subsequence on the reversed array
        # but computed directly: we look for elements to the right that are smaller than current
        lis_right = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, i, -1):
                if nums[j] < nums[i]:
                    lis_right[i] = max(lis_right[i], lis_right[j] + 1)

        min_removals = float('inf')

        # Iterate through possible peaks. A valid peak must have at least one element 
        # increasing before it and one decreasing after it.
        # So lis_left[i] >= 2 and lis_right[i] >= 2 ensures the mountain property.
        for i in range(1, n - 1):
            if lis_left[i] >= 2 and lis_right[i] >= 2:
                mountain_size = lis_left[i] + lis_right[i] - 1
                removals = n - mountain_size
                if removals < min_removals:
                    min_removals = removals

        return min_removals

