from typing import List

class Solution:
    def isOneBitCharacter(self, bits: List[int]) -> bool:
        # Algorithm Variant: Count consecutive ones from the start until a 0 is found or end
        # Logic: The last character is one-bit if the number of consecutive 1s before the last 0 is even.
        # However, the input always ends with 0. We just need to count how many 1s are immediately preceding the last 0 
        # after skipping all two-bit characters.
        # Alternative approach: Traverse backwards.
        # If we see a 0 at the end, check how many 1s precede it. If odd, the last char is part of a 2-char (11 or 10), so false.
        # If even, it's true.

        count = 0
        idx = len(bits) - 2
        while idx >= 0 and bits[idx] == 1:
            count += 1
            idx -= 1

        return count % 2 == 0

