class Solution:
    def minOperations(self, nums: List[int], target: List[int]) -> int:
        from collections import Counter

        if sum(nums) < target:
            return -1

        count = Counter()
        for num in nums:
            count[num] += 1

        operations = 0
        for i in range(30, -1, -1):
            val = 1 << i
            half_val = val >> 1

            # Try to use the current power of two to build the target
            if (target // val) % 2 == 1:
                if count[val] > 0:
                    count[val] -= 1
                else:
                    # Need to split a larger power of two
                    j = i + 1
                    while j <= 30 and count[1 << j] == 0:
                        j += 1
                    if j > 30:
                        return -1
                    # Split until we get enough of this value
                    while j > i:
                        count[1 << j] -= 1
                        count[1 << (j - 1)] += 2
                        operations += 1
                        j -= 1
                    count[val] -= 1
            # Carry over extra powers of two to smaller ones
            if count[val] > 1:
                extra = count[val] // 2
                count[val >> 1] += extra
                count[val] %= 2

        return operations
