class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        from collections import Counter

        if sum(nums) < target:
            return -1

        freq = Counter(nums)
        ans = 0

        for k in range(30, -1, -1):
            bit_val = 1 << k
            half_val = bit_val >> 1

            # If the k-th bit of target is required
            if (target >> k) & 1:
                if freq[bit_val] > 0:
                    freq[bit_val] -= 1
                else:
                    # Find a larger power to split
                    source = k + 1
                    while source <= 30 and freq[1 << source] == 0:
                        source += 1

                    if source > 30:
                        return -1

                    # Split down to k
                    while source > k:
                        freq[1 << source] -= 1
                        freq[1 << (source - 1)] += 2
                        ans += 1
                        source -= 1

                    freq[bit_val] -= 1

            # Move excess to next lower level
            if freq[bit_val] > 0:
                dup = freq[bit_val] // 2
                freq[half_val] += dup
                freq[bit_val] %= 2

        return ans

