    def minOperations(self, nums: List[int], target: int) -> int:
        from collections import defaultdict

        total_sum = 0
        for x in nums:
            total_sum += x
        if total_sum < target:
            return -1

        counts = defaultdict(int)
        for num in nums:
            counts[num] += 1

        operations = 0
        idx = 30
        while idx >= 0:
            current_val = 1 << idx
            half_val = current_val >> 1

            if (target // current_val) & 1:
                if counts[current_val] > 0:
                    counts[current_val] -= 1
                else:
                    search_idx = idx + 1
                    found = False
                    while search_idx <= 30:
                        if counts[1 << search_idx] > 0:
                            found = True
                            break
                        search_idx += 1

                    if not found:
                        return -1

                    while search_idx > idx:
                        counts[1 << search_idx] -= 1
                        counts[1 << (search_idx - 1)] += 2
                        operations += 1
                        search_idx -= 1

                    counts[current_val] -= 1

            extra = counts[current_val] // 2
            if extra > 0:
                counts[half_val] += extra
                counts[current_val] %= 2

            idx -= 1

        return operations

