from typing import List

class Solution:
    def numberOfBeams(self, bank: List[str]) -> int:
        device_counts = []
        for row in bank:
            cnt = row.count('1')
            if cnt > 0:
                device_counts.append(cnt)

        if len(device_counts) < 2:
            return 0

        beams = 0
        prev_count = device_counts[0]
        for i in range(1, len(device_counts)):
            curr_count = device_counts[i]
            beams += prev_count * curr_count
            prev_count = curr_count

        return beams

