class Solution:
    def copyRandomBinaryTree(self, root: 'Optional[Node]') -> 'Optional[NodeCopy]':
        if not root:
            return None

        # Dictionary to map original nodes to their copies
        node_map = {}

        # First pass: create all copies of nodes without setting left, right, or random
        def dfs_create(node):
            if not node:
                return None
            if node in node_map:
                return node_map[node]
            copy_node = NodeCopy(node.val)
            node_map[node] = copy_node
            return copy_node

        # Second pass: connect the copied nodes using the mapping
        def dfs_connect(node):
            if not node:
                return None
            copy_node = node_map[node]
            copy_node.left = dfs_connect(node.left)
            copy_node.right = dfs_connect(node.right)
            copy_node.random = node_map.get(node.random)  # Use get to handle null case
            return copy_node

        # Create and connect the copied tree
        dfs_create(root)
        return dfs_connect(root)

