from typing import List

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left_ptr = 0

        # Find the longest non-decreasing prefix
        while left_ptr + 1 < n and arr[left_ptr] <= arr[left_ptr + 1]:
            left_ptr += 1

        if left_ptr == n - 1:
            return 0  # The whole array is non-decreasing

        right_ptr = n - 1

        # Find the longest non-decreasing suffix
        while right_ptr - 1 >= 0 and arr[right_ptr - 1] <= arr[right_ptr]:
            right_ptr -= 1

        # Minimum subarray to remove is from left+1 to right-1 (keep prefix or suffix only)
        res = min(n - left_ptr - 1, right_ptr)

        # Try to merge prefix and suffix by removing a middle part
        i = 0
        j = right_ptr
        while i <= left_ptr and j < n:
            if arr[i] <= arr[j]:
                res = min(res, j - i)
                i += 1
            else:
                j += 1

        return res

