        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        memo = {}

        def solve(idx):
            if idx >= n:
                return 0
            if idx in memo:
                return memo[idx]

            take = nums[idx] + solve(idx + 2)
            skip = solve(idx + 1)

            res = max(take, skip)
