class Solution:
    def rob(self, nums: List[int]) -> int:
        if not nums:
            return 0
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        # Using a heap to simulate the DP transitions (conceptual variant)
        # Instead of array, we store potential max values and pop them
        # This is a structural variant replacing direct array access with heap logic
        import heapq

        # We push negative values because Python has min-heap
        # State: (max_money_up_to_i, index)
        # However, since we need strict O(N) and this is a mutation, 
        # we will use a list as a priority queue simulation where we always pick max.
        # But to strictly follow "Algorithm/Data-Structure Variant", let's swap to a deque based approach or simply sort?
        # No, sorting breaks order. Let's replace the linear scan with a recursive stack-based DFS traversal simulation.

        stack = [(0, 0)]  # (current_idx, current_max)
        best = 0

        while stack:
            idx, current_sum = stack.pop()
            if idx >= n:
                if current_sum > best:
                    best = current_sum
                continue

            # Option 1: Rob current house
            stack.append((idx + 2, current_sum + nums[idx]))
            # Option 2: Skip current house
            stack.append((idx + 1, current_sum))

        return best

