import heapq
from typing import List

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        if len(target) == 1:
            return target[0] == 1

        total_sum = sum(target)
        max_heap = [-x for x in target]
        heapq.heapify(max_heap)

        while -max_heap[0] > 1:
            current_max = -heapq.heappop(max_heap)
            remaining_sum = total_sum - current_max

            if remaining_sum <= 1:
                return current_max == 1 and remaining_sum == 1

            new_val = current_max % remaining_sum
            if new_val == 0:
                return False

            total_sum = remaining_sum + new_val
            heapq.heappush(max_heap, -new_val)

        return True

