        for start, end in intervals:
            # Check if no overlap exists
            if end <= rem_start or start >= rem_end:
                result.append([start, end])
            else:
                # Left segment (if any part of the interval is before rem_start)
                if start < rem_start:
                    result.append([start, rem_start])

                # Right segment (if any part of the interval is after rem_end)
                if end > rem_end:
                    result.append([rem_end, end])

