from typing import List

class Solution:
    def pivotArray(self, nums: List[int], pivot: int) -> List[int]:
        result = [0] * len(nums)
        left_ptr = 0
        right_ptr = len(nums) - 1
        equal_count = 0

        # First pass to count equals and place less/greater at ends
        # Actually, to maintain relative order, we need a different approach with two pointers
        # Let's use the logic of filling from both ends but tracking counts carefully isn't straightforward for stability
        # So let's use the recursive helper approach as a structural transformation variant 
        # that mimics the iterative split but via recursion

        def partition(arr, p):
            if not arr:
                return [], [], []
            head = arr[0]
            rest = arr[1:]
            sub_less, sub_equal, sub_greater = partition(rest, p)

            if head < p:
                return [head] + sub_less, sub_equal, sub_greater
            elif head == p:
                return sub_less, [head] + sub_equal, sub_greater
            else:
                return sub_less, sub_equal, [head] + sub_greater

        l, e, g = partition(nums, pivot)
        return l + e + g

