class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        char_counts = defaultdict(lambda: defaultdict(int))

        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            length = j - i
            c = s[i]

            # For a run of length 'length' of character 'c', 
            # the number of substrings of length 'l' is (length - l + 1).
            for l in range(1, length + 1):
                char_counts[c][l] += length - l + 1
            i = j

        max_len = -1

        for c in char_counts:
            for l in char_counts[c]:
                if char_counts[c][l] >= 3:
                    if l > max_len:
                        max_len = l

        return max_len

