class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache

        # Calculate prefix sums for quick sum queries
        prefix = [0] * (len(nums) + 1)
        idx = 0
        while idx < len(nums):
            prefix[idx + 1] = prefix[idx] + nums[idx]
            idx += 1

        def check_good(start_idx, end_idx):
            # Check if the subarray nums[start_idx..end_idx] is good
            length = end_idx - start_idx + 1
            total = prefix[end_idx + 1] - prefix[start_idx]
            return (length == 1) or (total >= m)

        @lru_cache(None)
        def solve(start_idx, end_idx):
            # Can we split nums[start_idx..end_idx] into all good arrays?
            if end_idx - start_idx + 1 == 1:
                return True

            split_point = start_idx
            while split_point < end_idx:
                left_part_good = check_good(start_idx, split_point)
                right_part_good = check_good(split_point + 1, end_idx)

                if left_part_good and right_part_good:
                    if solve(start_idx, split_point) and solve(split_point + 1, end_idx):
                        return True
                split_point += 1

            return False

        return solve(0, len(nums) - 1)

