class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache

        n = len(nums)
        prefix_sum = [0] * (n + 1)
        current = 0
        for i in range(n):
            current += nums[i]
            prefix_sum[i+1] = current

        def get_subarray_sum(l, r):
            return prefix_sum[r+1] - prefix_sum[l]

        def is_valid_segment(l, r):
            seg_len = r - l + 1
            seg_sum = get_subarray_sum(l, r)
            return seg_len == 1 or seg_sum >= m

        @lru_cache(maxsize=None)
        def recursive_check(l, r):
            if l == r:
                return True

            for mid in range(l, r):
                left_ok = is_valid_segment(l, mid)
                right_ok = is_valid_segment(mid + 1, r)

                if left_ok and right_ok:
                    if recursive_check(l, mid) and recursive_check(mid + 1, r):
                        return True
            return False

        return recursive_check(0, n - 1)

