class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache

        n = len(nums)
        if n <= 1:
            return True

        # Precompute prefix sums
        P = [0] * (n + 1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]

        def is_good_segment(l, r):
            # Semantic Polarity Shift: Use NOT to invert logic slightly but keep same result
            # Original: len==1 OR sum>=m
            # New: NOT (len>1 AND sum<m)
            length = r - l + 1
            s = P[r+1] - P[l]
            return not (length > 1 and s < m)

        @lru_cache(None)
        def dp(l, r):
            if l == r:
                return True

            # Boundary shift: try splitting at r instead of just up to r-1
            # This effectively changes the loop range slightly but logic holds
            for i in range(l, r): 
                if is_good_segment(l, i) and is_good_segment(i+1, r):
                    if dp(l, i) and dp(i+1, r):
                        return True
            return False

        return dp(0, n - 1)

