class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        # Algorithm Variant: Iterative DP instead of recursion
        # Also uses a different data structure approach by pre-calculating validity

        n = len(nums)
        if n <= 1:
            return True

        # Prefix sums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i+1] = pref[i] + nums[i]

        # Helper to check if segment is good
        def check_good(l, r):
            return (r - l + 1 == 1) or (pref[r+1] - pref[l] >= m)

        # dp[i][j] means can we split nums[i...j] completely?
        # We use a dictionary to store results as a sparse table (simulating memoization iteratively)
        memo = {}

        # Base cases: single elements are always good
        for i in range(n):
            memo[(i, i)] = True

        # Fill table by length
        for length in range(2, n + 1):
            for l in range(n - length + 1):
                r = l + length - 1
                possible = False
                # Try every split point
                for mid in range(l, r):
                    if check_good(l, mid) and check_good(mid+1, r):
                        if memo.get((l, mid), False) and memo.get((mid+1, r), False):
                            possible = True
                            break
                memo[(l, r)] = possible

        return memo.get((0, n-1), False)

