class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache

        # Calculate prefix sums for quick sum queries
        prefix = [0] * (len(nums) + 1)
        for i in range(len(nums)):
            prefix[i + 1] = prefix[i] + nums[i]

        def is_good(l, r):
            # Check if the subarray nums[l..r] is good
            return (r - l + 1 == 1) or (prefix[r + 1] - prefix[l] >= m)

        @lru_cache(None)
        def dp(l, r):
            # Can we split nums[l..r] into all good arrays?
            if r - l + 1 == 1:
                return True
            for i in range(l, r):
                left = nums[l:r - i + l]
                right = nums[r - i + l:r + 1]
                if is_good(l, i) and is_good(i + 1, r) and dp(l, i) and dp(i + 1, r):
                    return True
            return False

        return dp(0, len(nums) - 1)

