from typing import List

class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        n = len(colors)
        if n == 0:
            return 0

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        max_size = 0

        def dfs(node: int, parent: int) -> int:
            nonlocal max_size

            # Start with size 1 (the node itself) and assume it's valid
            current_color = colors[node]
            subtree_size = 1
            is_valid = True

            for child in adj[node]:
                if child == parent:
                    continue

                child_result = dfs(child, node)

                # If any child subtree is invalid or has a different color, this subtree is invalid
                if child_result == -1 or colors[child] != current_color:
                    is_valid = False
                    break

                subtree_size += child_result

            if is_valid:
                max_size = max(max_size, subtree_size)
                return subtree_size
            else:
                return -1

        dfs(0, -1)
        return max_size

