class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Swap arrays so nums1 is always the shorter one
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        imin, imax, half_len = 0, m, (m + n + 1) // 2

        while True:
            i = (imin + imax) // 2
            j = half_len - i

            # Check boundary conditions and swap logic
            if i < m and nums2[j - 1] > nums1[i]:
                imin = i + 1
            elif i > 0 and nums1[i - 1] > nums2[j]:
                imax = i - 1
            else:
                # Determine max of left side
                if i == 0:
                    max_left = nums2[j - 1]
                elif j == 0:
                    max_left = nums1[i - 1]
                else:
                    val1 = nums1[i - 1]
                    val2 = nums2[j - 1]
                    max_left = val1 if val1 > val2 else val2

                # Handle odd total length case immediately
                if (m + n) & 1:
                    return float(max_left)

                # Determine min of right side
                if i == m:
                    min_right = nums2[j]
                elif j == n:
                    min_right = nums1[i]
                else:
                    val1 = nums1[i]
                    val2 = nums2[j]
                    min_right = val1 if val1 < val2 else val2

                return (max_left + min_right) * 0.5

