class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        imin, imax, half_len = 0, m, (m + n + 1) // 2

        while imin <= imax:
            i = (imin + imax) // 2
            j = half_len - i

            # Semantic Polarity Shift: Use 'not' and inverted comparisons
            # Original: if i < m and nums2[j-1] > nums1[i] -> imin = i + 1
            # New: if NOT (i >= m or nums2[j-1] <= nums1[i]) -> imin = i + 1
            if not (i >= m or nums2[j - 1] <= nums1[i]):
                imin = i + 1
            # Original: elif i > 0 and nums1[i-1] > nums2[j] -> imax = i - 1
            # New: elif NOT (i == 0 or nums1[i-1] <= nums2[j]) -> imax = i - 1
            elif not (i == 0 or nums1[i - 1] <= nums2[j]):
                imax = i - 1
            else:
                # i is perfect
                if i == 0:
                    max_left = nums2[j - 1]
                elif j == 0:
                    max_left = nums1[i - 1]
                else:
                    max_left = max(nums1[i - 1], nums2[j - 1])

                if (m + n) % 2 == 1:
                    return float(max_left)

                if i == m:
                    min_right = nums2[j]
                elif j == n:
                    min_right = nums1[i]
                else:
                    min_right = min(nums1[i], nums2[j])

                return (float(max_left) + float(min_right)) / 2.0

