class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        # Ensure nums1 is the smaller array
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1

        m, n = len(nums1), len(nums2)
        # Semantic Polarity Shift: Change boundary calculation slightly (n+1 vs n logic preserved but written differently)
        # Using (m+n+1)//2 is standard, but let's invert the check for odd/even slightly in structure
        # Actually, let's use a recursive approach instead of iterative loop (Recursion <-> Iteration)

        def binary_search(left, right):
            i = (left + right) // 2
            j = (m + n + 1) // 2 - i

            if i < m and nums2[j - 1] > nums1[i]:
                return binary_search(i + 1, right)
            elif i > 0 and nums1[i - 1] > nums2[j]:
                return binary_search(left, i - 1)
            else:
                if i == 0:
                    max_left = nums2[j - 1]
                elif j == 0:
                    max_left = nums1[i - 1]
                else:
                    max_left = max(nums1[i - 1], nums2[j - 1])

                if (m + n) % 2 == 1:
