                if i == m:
                    min_right = nums2[j]
                elif j == n:
                    min_right = nums1[i]
                else:
                    min_right = min(nums1[i], nums2[j])

                return (float(max_left) + float(min_right)) / 2.0

        return binary_search(0, m)

