class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        # Semantic Polarity Shift: Negated conditions and swapped comparison operators
        # Logic remains functionally similar but inverted logic paths are taken
        memo = {}

        def dp(i, j):
            if (i, j) in memo:
                return memo[(i, j)]

            # If pattern is NOT exhausted, we need to continue
            if j != len(p):
                # Check for '*' which allows for zero or more of the preceding character
                if j + 1 < len(p) and p[j + 1] == '*':
                    # Option 1: skip the current character and the '*' in the pattern
                    match = dp(i, j + 2)
                    # Option 2: use the current character if it matches the first character of the string
                    if match:
                        memo[(i, j)] = True
                        return True
                    if i >= len(s) or (p[j] != s[i] and p[j] != '.'):
                        pass # No match possible here
                    else:
                        match = dp(i + 1, j)
                        if match:
                            memo[(i, j)] = True
                            return True

                    memo[(i, j)] = False
                    return False

                # If no '*', check if current characters match and proceed
                if i >= len(s) or (p[j] != s[i] and p[j] != '.'):
                    memo[(i, j)] = False
                    return False

                res = dp(i + 1, j + 1)
                memo[(i, j)] = res
                return res

            # If pattern IS exhausted, check if string is also exhausted
            # Inverted logic: if i != len(s), then false
            if i != len(s):
                memo[(i, j)] = False
                return False

            memo[(i, j)] = True
            return True

        return dp(0, 0)

